import { ProductionLine } from '@/cdc/modules/production-line/production-line.entity';
import { Resource } from '@/cdc/modules/resource/resource.entity';
import { ResourceType } from '@/cdc/modules/resource-type/resource-type.entity';
import { Uap } from '@/cdc/modules/uap/uap.entity';
import { Workcenter } from '@/cdc/modules/workcenter/workcenter.entity';
import { Plant } from '@/shared/plant/plant.entity';

export interface Mapping {
  /**
   * Source table in SAP DMC
   */
  source: string;

  /**
   * Target table in MESX
   */
  destination: string;
  /**
   * Cache treatment  in MESX
   */
  cacheTreatment: boolean;
  /**
   * Key fields source and associated column in target structure
   */
  keys: Array<KeyMapping>;

  /**
   * Column mapping
   */
  columnMappings: Array<ColumnMapping>;
}

export interface KeyMapping {
  /**
   * Source field
   */
  keySource: string;

  /**
   * Target field
   */
  keyDestination: string;

  /**
   * If not optional we expect to have target field valuated
   */
  optional?: boolean;
}

export interface ColumnMapping {
  /**
   * Source field
   */
  columnSource: string;

  /**
   * Target field
   */
  columnDestination: string;

  /**
   * AllowEmpty field
   */
  allowEmpty?: boolean;
}
export type MappedOutput =
  | Plant
  | ProductionLine
  | Uap
  | Workcenter
  | Resource
  | ResourceType;
export interface KeysValueArray {
  [key: string]: number | string;
}

import { CommonDto } from '@/cdc/dapr/dto/common.dto';

export interface ResourceTypeConvert extends CommonDto {
  [key: string]: number | string | boolean | undefined;

  /**
   * Plant
   */
  plant: number;

  /**
   * Resource id in MESX
   */
  resourceId: string;

  /**
   * Resource type  in MESX
   */
  resourceType: string;
}

