@Controller('')
export class DaprController {
  public constructor(
    private readonly daprService: DaprService,
    private readonly customLogger: AppLogger,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly resourceTypeConvertService: ResourceTypeConvertService,
  ) {}

  /**
   * Process a standard event with common logging
   * @param request Request
   * @param methodName Method name for logging
   * @param topic Topic name for telemetry
   * @returns Promise<string>
   */
  private async processStandardEvent(
    request: Request,
    methodName: string,
    topic: string,
  ): Promise<string> {
    const startTime = Date.now();
    const event = request.body;
    const plantCode =
      event?.S_SITE || event?.SITE || event?.S_PLANT || event?.PLANT;

    if (topic) {
      try {
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.RECEIVED,
          plantCode,
          topic,
        );
      } catch {
        // Silent fail - don't break processing if telemetry fails
      }
    }
    try {
      const result = await this.daprService.handleMessage(event);
      if (result.processed) {
        const duration = Date.now() - startTime;
        telemetryMetrics.trackEventProcessingDuration(
          duration,
          PROCESSING_STATUS.PROCESSED,
          String(plantCode),
          topic,
        );
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.PROCESSED,
          String(plantCode),
          topic,
        );
      }
      return `OK${methodName}`;
    } catch (error) {
      const duration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        duration,
        PROCESSING_STATUS.INVALID,
        String(plantCode),
        topic,
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.INVALID,
        String(plantCode),
        topic,
      );
      throw error;
    }
  }

  @Post(bindings.bindingPlant)
  public async receiveEventPlant(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(request, 'receiveEventPlant', 'plant');
  }

  @Post(bindings.bindingProdline)
  public async receiveEventProdLine(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventProdline',
      'production-line',
    );
  }

  @Post(bindings.bindingResource)
  public async receiveEventtResource(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventResource',
      'resource',
    );
  }

  @Post(bindings.bindingResourceTypeResource)
  public async receiveEventResourceTypeResource(
    @Req() request: Request,
  ): Promise<string> {
    const context: JobsLogContext = {
      method: 'checkPayloadConsistency:bindingResourceTypeResource',
      service: 'DaprService',
    };
    if (!checkPayloadConsistency(this.customLogger, context, request.body))
      return 'OK';

    const converted = await this.resourceTypeConvertService.convert(
      request.body,
    );
    request.body = converted;
    return this.processStandardEvent(
      request,
      'receiveEventResourceTypeResource',
      'resource-type',
    );
  }

  @Post(bindings.bindingUAP)
  public async receiveEventUAP(@Req() request: Request): Promise<string> {
    return this.processStandardEvent(request, 'receiveEventUAP', 'uap');
  }

  @Post(bindings.bindingWorkCenter)
  public async receiveEventWorkCenter(
    @Req() request: Request,
  ): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventWorkCenter',
      'workcenter',
    );
  }

  @Post(bindings.bindingWorkCenterList)
  public async receiveEventWorkCenterList(
    @Req() request: Request,
  ): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventWorkCenterList',
      'workcenter-list',
    );
  }

  @Post(bindings.topicPlants)
  public async initPlant(@Req() request: Request): Promise<string> {
    const context = DaprService.createLogContext('initPlant');
    try {
      const data = request.body;
      await this.subscribeMessageService.handleMessage(data);
      await this.daprService.initializePlant();
      this.customLogger.debug(`Updated Plants List`, context);
      return 'OK';
    } catch (error) {
      this.customLogger.error(
        `Error processing event: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }
}

