  message: CombinedDtoWithIndex | RedisMessage,
  action: MESSAGE_ACTION,
): Promise<void> {
  try {
    const deadLetterQueueKey = `${key}-dead-letter-${action}`;

    let dateStart = Date.now();
    const currentState = await daprClient.state.get(
      redisStoreAmr,
      deadLetterQueueKey,
    );
    logger.debug(
      [
        `Time taken to get state in moveToDeadLetterQueue`,
        `on key ${key}: ${Date.now() - dateStart} ms,`,
        `(waitingMsgCount: ${getPendingMessagesCount()})`,
      ].join(' '),
      context,
    );

    const oldCachedData = currentState.valueOf()
      ? Object.values(currentState.valueOf())
      : [];

    const dataToCache = {
      key: deadLetterQueueKey,
      value: [...oldCachedData, message],
    };

    logger.error(
      `Moving message for ${key} to dead letter queue: ${JSON.stringify(
        message,
      )}`,
      context,
    );

    dateStart = Date.now();

    await daprClient.state.save(redisStoreAmr, [dataToCache]);

    logger.debug(
      [
        `Time taken to save state in moveToDeadLetterQueue`,
        `on key ${key}: ${Date.now() - dateStart} ms,`,
        `(waitingMsgCount: ${getPendingMessagesCount()})`,
      ].join(' '),
      context,
    );
  } catch (error) {
    logger.error(
      `Failed to move message for ${key} to dead letter queue: ${error.message}`,
      context,
      error.stack,
    );
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Mutex } from 'async-mutex';
import { DaprClient } from 'dapr-client';
import { acquireLockWithTimeout } from '../locks/acquire-lock';
import { getPendingMessagesCount } from '../statistics/pending-message-stats';
import { moveToDeadLetterQueue } from './move-to-dead-letter-queue';
import { MESSAGE_ACTION } from '@/cdc/dapr/interface/enum-message-action.interface';
import { RedisMessage } from '@/cdc/dapr/interface/redis-message-data.interface';
import { AppLogger } from '@/shared/logger/app-logger';

/**
 * Remove the message Queue
 * @param logger Application logger
 * @param serviceMutexes mutex register
 * @param daprClient dapr client
 * @param queue queue input structure
 * @param queue.redisStoreNameAmr store name for state call (AMR)
 * @param queue.inMemoryQueue in memory queue
 * @param queue.processingQueue in memory processing queue
 * @param queue.queueKey queue key where to remove the record
 * @param message message to remove
 * @returns void
 */
export async function removeMessageQueue(
  logger: AppLogger,
  serviceMutexes: Record<string, Mutex>,
  daprClient: DaprClient,
  queue: {
    inMemoryQueue: Record<string, Array<RedisMessage>>;
    processingQueue: Record<string, boolean>;
    queueKey: string;
    redisStoreNameAmr: string;
  },
  message: RedisMessage,
): Promise<void> {
  const context: JobsLogContext = {
    method: 'removeMessageQueue',
    service: 'removeMessageQueue',
  };
  const moveToDeadLetterQueueContext: JobsLogContext = {
    method: 'moveToDeadLetterQueue',
    service: 'removeMessageQueue',
  };
  const { redisStoreNameAmr, inMemoryQueue, processingQueue, queueKey } = queue;
  let dateStart = Date.now();

  const acquireLockContext: JobsLogContext = {
    method: 'acquireLockWithTimeout',
    service: 'removeMessageQueue',
  };

  const release = await acquireLockWithTimeout(
    acquireLockContext,
    logger,
    serviceMutexes,
    queueKey,
  );
  logger.debug(
    [
      `Time taken to acquire lock (removeMessageQueue): ${message.keysValue}`,
      `on key ${queueKey}: ${Date.now() - dateStart} ms,`,
      `(waitingMsgCount: ${getPendingMessagesCount()})`,
    ].join(' '),
    acquireLockContext,
  );

  if (!release) {
    logger.warn(
      `Failed to acquire priority lock for removing queue ${queueKey}, skipping.`,
      acquireLockContext,
    );
    await moveToDeadLetterQueue(
      moveToDeadLetterQueueContext,
      logger,
      redisStoreNameAmr,
      daprClient,
      queueKey,
      message,
      MESSAGE_ACTION.REMOVE,
    );
    return;
  }

  try {
    // Retrieve the Redis queue for this binding
    dateStart = Date.now();
    inMemoryQueue[queueKey].shift();
    const processingQueueAlias = processingQueue;
    processingQueueAlias[queueKey] = inMemoryQueue[queueKey].length > 0;
    logger.debug(
      [
        `Time taken to save state (queue size ${inMemoryQueue[queueKey].length}) (removeMessageQueue) for : ${message.keysValue}`,
        `on key ${queueKey}: ${Date.now() - dateStart} ms,`,
        `(waitingMsgCount: ${getPendingMessagesCount()})`,
      ].join(' '),
      context,
    );
  } catch (error) {
    logger.error(
      `Error processing Message for ${queueKey}: ${error.message}`,
      error.stack,
    );
    await moveToDeadLetterQueue(
      moveToDeadLetterQueueContext,
      logger,
      redisStoreNameAmr,
      daprClient,
      queueKey,
      message,
      MESSAGE_ACTION.REMOVE,
    );
  } finally {
    if (release) {
      release();
    }
    logger.debug(`End of removing message queue for ${queueKey}`, context);
  }
}

import { randomInt } from 'node:crypto';
import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '@/shared/logger/app-logger';

/**
 * Calculates the delay for the next retry attempt using exponential backoff with a random jitter.
 * @param attempt - The current attempt number.
 * @param maxBackoff - The maximum backoff time in seconds.
 * @returns The calculated delay in milliseconds.
 */
export function calculateExponentialBackoffDelay(
  attempt: number,
  maxBackoff: number,
): number {
  const randomNumberMilliseconds = randomInt(0, 1000); // Random number between 0 and 1000
  const exponentialDelay = 2 ** attempt; // 2^n
  return Math.min(
    exponentialDelay * 1000 + randomNumberMilliseconds,
    maxBackoff * 1000,
  ); // Convert seconds to milliseconds
}

/**
 * Retries a given operation a specified number of times with an exponential backoff delay between attempts.
 * @template T The type of the result returned by the operation.
 * @param logger - Logger instance for logging.
 * @param context Job Log Context
 * @param operation - The operation to retry.
 * @param [retries] - Number of retry attempts.
 * @param [baseDelayMs] - Base delay between retries in milliseconds.
 * @param [jitter] - Whether to add randomness to the delay.
 * @param [attempt] - Current attempt number.
 * @param maxBackoff -max delay
 * @param customRetryableCheck - Optional predicate to override the default retryable-error detection.
 * @returns A promise that resolves to the result of the operation.
 * @throws Will throw an error if the operation fails after the specified number of retries.
 */
export async function exponentialBackoffRetry<T>(
  logger: AppLogger,
  context: JobsLogContext,
  operation: () => Promise<T>,
  retries = 5,
  baseDelayMs = 1000,
  jitter = true,
  attempt = 1,
  maxBackoff = 32,
  customRetryableCheck?: (error: Error) => boolean,
): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    const normalizedError = error as Error & {
      code?: number;
      message?: string;
      name?: string;
    };
    const message = normalizedError.message ?? '';
    const { code } = normalizedError;

    const defaultRetryableError =
      // If Redis returns a 5xx-like error (this would depend on the client you're using)
      code === 429 ||
      (typeof code === 'number' && code >= 500 && code < 600) ||
      message.includes('The client is closed') ||
      // Network or connection errors (Socket closed in case of redis infra redeploy)
      message.includes('Socket closed unexpectedly') ||
      // Network or connection errors (AbortError)
      normalizedError.name === 'AbortError' ||
      // Redis errors that indicate retryable conditions
      (normalizedError.name === 'ReplyError' &&
        (message.includes('TRYAGAIN') || message.includes('READONLY')));

    const isRetryableError = customRetryableCheck
      ? customRetryableCheck(normalizedError)
      : defaultRetryableError;
    if (!isRetryableError) {
      logger.error(`Non-retryable error encountered: ${message}`, context);
      throw error; // Non-retryable error, rethrow
    }

    if (attempt >= retries) {
      logger.error(
        `Operation failed after ${retries} retries: ${(error as Error).message}`,
        context,
      );
      throw error;
    }
    // Calculate delay
    const delay = jitter
      ? calculateExponentialBackoffDelay(attempt, maxBackoff)
      : baseDelayMs * 2 ** (attempt - 1);
    logger.warn(
      `Retrying operation (${attempt}/${retries}) after error: ${(error as Error).message}`,
      context,
    );

    await new Promise((resolve) => {
      setTimeout(resolve, delay);
    });
    return exponentialBackoffRetry(
      logger,
      context,
      operation,
      retries,
      delay,
      jitter,
      attempt + 1,
      maxBackoff,
      customRetryableCheck,
    );
  }
}

import * as crypto from 'node:crypto';
import * as fs from 'node:fs/promises';
import * as path from 'node:path/posix';
import { RedisMessage } from '@/cdc/dapr/interface/redis-message-data.interface';
import { AppLogger } from '@/shared/logger/app-logger';

/**
 * Hook called before application shutdown
 * @param logger logger
 * @param inMemoryQueue inMemory queue
 * @param queueBackupBasePath queue backup base path
 * @param microServiceName micro service name
 * @param signal killing signal
 */
export async function beforeApplicationShutdown(
  logger: AppLogger,
  inMemoryQueue: Record<string, Array<RedisMessage>>,
  queueBackupBasePath: string,
  microServiceName: string,
  signal: string,
): Promise<void> {
  const context = {
    method: 'beforeApplicationShutdown',
    service: 'daprService',
  };
  try {
    logger.debug(
      `beforeApplicationShutdown - Received signal ${signal}`,
      context,
    );
    await Promise.all(
      Object.keys(inMemoryQueue).map(async (key) => {
        const dataQueue = inMemoryQueue[key];
        const uniqueId = crypto.randomUUID();

        // Adjust the file path to include the queue name and UUID in the filename
        const filePath = path.join(
          queueBackupBasePath,
          microServiceName,
          `queue-${key}-${uniqueId}.json`,
        );

        try {
          // Ensure the base folder exists (not queue specific anymore)
          await fs.mkdir(path.join(queueBackupBasePath, microServiceName), {
            recursive: true,
          });

          // Write the JSON data to the file
          if (dataQueue.length > 0) {
            await fs.writeFile(
              filePath,
              JSON.stringify(dataQueue, undefined, 2),
            );

            logger.log(
              `beforeApplicationShutdown - Successfully backed up ${key} queue to ${filePath}.`,
              context,
            );
          } else {
            logger.log(
              `beforeApplicationShutdown - No data found for queue${key}`,
              context,
            );
          }
        } catch (fileError) {
          logger.error(
            `Error backing up ${key} queue: ${fileError.message}`,
            fileError.stack,
          );
        }
      }),
    );
  } catch (error) {
    logger.error(
      `Error backing up queues: ${error.message}`,
      context,
      error.stack,
    );
  }
}

import { Mutex } from 'async-mutex';

export const pendingMessageStats = {
  count: 0,
};

export const pendingMessageCountMutex = new Mutex();

/**
 * Increment the general counter
 */
export function incrementPendingMessageCount(): void {
  pendingMessageCountMutex.runExclusive(() => {
    pendingMessageStats.count += 1;
  });
}

/**
 * Decrement the general counter
 */
export function decrementPendingMessageCount(): void {
  pendingMessageCountMutex.runExclusive(() => {
    pendingMessageStats.count -= 1;
  });
}

/**
 * Return count property from pendingMessageStats
 * @returns count property
 */
export function getPendingMessagesCount(): number {
  return pendingMessageStats.count;
}

import { JobsLogContext } from '@mesx/common-lib';
import { CombinedDtoWithIndex } from '@/cdc/dapr/dto/combine.dto';
import { AppLogger } from '@/shared/logger/app-logger';

/**
 * Check if payload is consistent
 * @param logger Application logger
 * @param context Job Log Context
 * @param record - The record to check for consistency
 * @returns - Returns true if the payload is consistent, false otherwise
 */
export function checkPayloadConsistency(
  logger: AppLogger,
  context: JobsLogContext,
  record: CombinedDtoWithIndex,
): boolean {
  if (!record) {
    logger.verbose(`Error: payload is empty`, context);
    return false;
  }

  const { __source_table: sourceTable, __op: operation } = record;
  if (!sourceTable) {
    logger.verbose(`Error: Table source undefined`, context);
    return false;
  }

  if (!['c', 'u', 'r', 'd'].includes(operation ?? '')) {
    logger.verbose(`Error: Unknown operation ${operation}`, context);
    return false;
  }

  return true;
}

import { MappedOutput } from '@/cdc/common/mapping/interface/mapping.model';
import { AppLogger } from '@/shared/logger/app-logger';
import { PlantsResponseDto } from '@/shared/subscribe/dtos/plant.response.dto';

/**
 * Check if plant consistency
 * @param logger - Application logger
 * @param mappedData - The mapped data
 * @param listPlant - List Plant
 * @param sourceTable Table source
 * @returns - Returns true if plant is consistent, false otherwise
 */
export function checkPlantConsistency(
  logger: AppLogger,
  mappedData: MappedOutput,
  listPlant: Array<PlantsResponseDto>,
  sourceTable: string | null | undefined,
): boolean {
  const context = {
    method: 'checkPlantConsistency',
    service: 'checkPlantConsistency',
  };
  try {
    if (sourceTable !== 'CONFIG_SERVER') {
      const check = listPlant.some(
        (plant: PlantsResponseDto) =>
          plant.plantId === Number(mappedData.plant),
      );
      if (!check) {
        logger.verbose(
          `Plant ${mappedData.plant} is not defined in the plant list`,
          context,
        );
      }
      return check;
    }
    const plantCheck = listPlant.some(
      (plant: PlantsResponseDto) =>
        plant.plantId === Number(mappedData.plantId),
    );
    if (!plantCheck) {
      logger.verbose(
        `Plant ${mappedData.plantId} is not defined in the plant list`,
        context,
      );
    }
    return plantCheck;
  } catch (error) {
    logger.error(`Error processing message: ${error}`, context, error.stack);
  }
  return false; // Return false in case of an error or if no other return statement is reached
}

import { IngestionEventTrackingDTO } from '@/shared/ingestion-event-tracking/ingestion-event-tracking.dto.';
import { IngestionEventTrackingService } from '@/shared/ingestion-event-tracking/ingestion-event-tracking.service';
import { AppLogger } from '@/shared/logger/app-logger';

/**
 *
 * @param logger App logger²
 * @param ingestionEventTrackingService to check timestamp
 * @param ingestionEventTracking - The Ingestion Event tracking Dto
 * @returns - Returns a promise that resolves to a boolean indicating the success of the operation.
 */
export async function validateAndTrackChanges(
  logger: AppLogger,
  ingestionEventTrackingService: IngestionEventTrackingService,
  ingestionEventTracking: IngestionEventTrackingDTO,
): Promise<boolean> {
  const context = {
    method: 'validateAndTrackChanges',
    service: 'validateAndTrackChanges',
  };
  if (!ingestionEventTracking) {
    logger.error(
      'Validation failed: ingestionEventTracking is undefined.',
      context,
    );
    return false;
  }
  const {
    changeLastLsn,
    lastTimestamp,
    destinationTable,
    hashKey,
    keys,
    sourceTable,
  } = ingestionEventTracking;
  if (
    changeLastLsn === undefined ||
    lastTimestamp === undefined ||
    hashKey === undefined ||
    keys === undefined ||
    sourceTable === undefined
  ) {
    logger.error(
      `Validation failed: Missing properties in ingestionEventTracking. ` +
        `Received changeLastLsn: ${changeLastLsn}, lastTimestamp: ${lastTimestamp}, ` +
        `destinationTable: ${destinationTable}, hashKey: ${hashKey}, keys: ${keys}, sourceTable: ${sourceTable}.`,
      context,
    );
    return false;
  }
  try {
    const isDataCurrent =
      await ingestionEventTrackingService.verifyAndTrackIngestionEventTrackingCache(
        ingestionEventTracking,
      );

    if (!isDataCurrent) {
      logger.warn(
        `Outdated data detected for table "${sourceTable}". ` +
          `Timestamp: ${lastTimestamp}, Last LSN: ${changeLastLsn}.`,
        context,
      );
      return false;
    }

    return true;
  } catch (error) {
    logger.error(
      `Error while verifying and tracking ingestion event for table "${sourceTable}": ${error.message}`,
      context,
      error.stack,
    );
    return false;
  }
}

