import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { ProductionLine } from '@/cdc/modules/production-line/production-line.entity';
import { AppLogger } from '@/shared/logger/app-logger';

@Injectable()
export class ProductionLineService {
  private readonly context: JobsLogContext = {
    method: '',
    service: ProductionLineService.name,
  };

  public constructor(
    @InjectRepository(ProductionLine)
    private readonly productionLineRepository: Repository<ProductionLine>,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('productionLine.c')
  private async create(payload: ProductionLine): Promise<void> {
    this.context.method = 'create productionLine.c ';
    if (!payload)
      return this.customLogger.error(
        `payload is empty ${payload}`,
        this.context,
      );
    try {
      const { ...productionLineData } = payload;
      const sqlStartTime = Date.now();
      await this.productionLineRepository.upsert(
        { ...productionLineData, updatedAt: () => 'SYSUTCDATETIME()' },
        { conflictPaths: ['prodLineId', 'plant'] },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'productionLine',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'productionLine',
      );
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base and publish message : ${error.message}`,
        this.context,
        error.stack,
      );
    }
    return undefined;
  }

  @OnEvent('productionLine.u')
  private async updateByProductionLineIdAndPlant(
    payload: ProductionLine,
  ): Promise<void> {
    this.context.method = 'updateByProductionLineIdAndPlant ';
    if (!payload) {
      this.customLogger.error('Payload is empty', this.context);
      return;
    }

    const { prodLineId, plant, ...productionLineData } = payload;

    if (!prodLineId || !plant) {
      this.customLogger.error(
        'Invalid payload: missing prodLineId or plant',
        this.context,
      );
      return;
    }

    try {
      const sqlStartTime = Date.now();
      await this.productionLineRepository.upsert(
        {
          prodLineId,
          plant,
          ...productionLineData,
          updatedAt: () => 'SYSUTCDATETIME()',
        }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['prodLineId', 'plant'] },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'productionLine',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'productionLine',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating production line: ${error.message}`,
        this.context,
      );
    }
  }

  @OnEvent('productionLine.r')
  private async readSnapshot(payload: ProductionLine): Promise<void> {
    this.context.method = 'readSnapshot ';
    if (!payload)
      return this.customLogger.error(
        `payload is empty${payload}`,
        this.context,
      );

    try {
      const { prodLineId, plant, ...productionLineData } = payload;
      const sqlStartTime = Date.now();
      await this.productionLineRepository.upsert(
        {
          prodLineId,
          plant,
          ...productionLineData,
          updatedAt: () => 'SYSUTCDATETIME()',
        }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['prodLineId', 'plant'] },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'productionLine',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'productionLine',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating production line: ${error.message}`,
        this.context,
      );
      throw new HttpException(
        `error in updating data ${error}`,
        HttpStatus.BAD_REQUEST,
      );
    }
    return undefined;
  }
}

