@Injectable()
export class ResourceTypeService {
  private readonly context: JobsLogContext = {
    method: '',
    service: ResourceTypeService.name,
  };

  public constructor(
    @InjectRepository(ResourceType)
    private readonly resourceTypeRepository: Repository<ResourceType>,
    private readonly resourceService: ResourceService,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('resourceType.d')
  private async delete(payload: ResourceType): Promise<void> {
    this.context.method = 'delete';
    if (!payload) {
      return this.customLogger.error(
        `payload is empty ${payload}`,
        this.context,
      );
    }
    const { resourceId, plant, resourceType } = payload;

    if (!resourceId || !plant || !resourceType) {
      this.customLogger.error(
        'Invalid payload: missing resourceId or plant or resourceType',
        this.context,
      );
      return undefined;
    }

    try {
      const sqlStartTime = Date.now();
      const result = await this.resourceTypeRepository.delete({
        resourceId: String(resourceId),
        plant: Number(plant),
