    TypeOrmModule.forFeature([Workcenter]),
    EventhubModule,
    PublishMessageModule,
  ],
  providers: [WorkcenterService],
})
export class WorkcenterModule {}

import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm/repository/Repository';
import { KeysValueArray } from '@/cdc/common/mapping/interface/mapping.model';
import { Workcenter } from '@/cdc/modules/workcenter/workcenter.entity';
import { EventhubService } from '@/shared/config/eventhub/eventhub.service';
import { AppLogger } from '@/shared/logger/app-logger';
import { PublishMessageService } from '@/shared/publish-message/publish-message.service';

@Injectable()
export class WorkcenterService {
  /**
   * Parses a value to a number, returning undefined for invalid values
   * @param value - The value to parse into a number
   * @returns The parsed number or undefined if the value is invalid
   */
  private static parseNumber(value: unknown): number | null {
    if (value === null || value === '') return null;
    const parsed = Number(value);
    return Number.isNaN(parsed) ? null : parsed;
  }

  /**
   * Transforms string values to numbers for launcher waiting time fields
   * @param data - Partial workcenter object whose launcher waiting time fields
   * may be strings and should be converted to numbers when possible.
   * Fields handled: `minLauncherWaitingTime`, `maxLauncherWaitingTime`.
   * @returns The input object with launcher waiting time fields parsed to
   * numbers when valid, or left as `undefined` when parsing fails.
   */
  private static transformWorkcenterData<T extends Partial<Workcenter>>(
    data: T,
  ): T {
    return {
      ...data,
      minLauncherWaitingTime:
        data.minLauncherWaitingTime === undefined
          ? data.minLauncherWaitingTime
          : WorkcenterService.parseNumber(data.minLauncherWaitingTime),
      maxLauncherWaitingTime:
        data.maxLauncherWaitingTime === undefined
          ? data.maxLauncherWaitingTime
          : WorkcenterService.parseNumber(data.maxLauncherWaitingTime),
    };
  }

  private readonly context: JobsLogContext = {
    method: '',
    service: WorkcenterService.name,
  };

  public constructor(
    @InjectRepository(Workcenter)
    private readonly workcenterRepository: Repository<Workcenter>,
    private readonly customLogger: AppLogger,
    private readonly publishMessageService: PublishMessageService,
    private readonly eventhubService: EventhubService,
  ) {}

  public async findWorkcenter(
    payload: KeysValueArray,
  ): Promise<string | undefined> {
    this.context.method = 'findWorkcenter';
    const { plant, workcenterId } = payload;
    try {
      const result: string | undefined = await this.workcenterRepository
        .createQueryBuilder('workcenter')
        .select('workcenter_id as workcenterId')
        .where(
          'workcenter.plant= :plant AND workcenter.workcenter_id=:workcenterId',
          { plant, workcenterId },
        )
        .getRawOne();
      return result;
    } catch (error) {
      this.customLogger.error(error, this.context);
      throw new HttpException(
        ' Query get workcenter Failed',
        HttpStatus.BAD_REQUEST,
      );
    }
  }

  @OnEvent('workcenter.c')
  private async create(payload: Workcenter): Promise<void> {
    this.context.method = 'create';
    if (!payload)
      return this.customLogger.error(
        `payload is empty ${payload}`,
        this.context,
      );
    try {
      const { tableChangeLog, ...workcenterData } = payload;
      const transformedData =
        WorkcenterService.transformWorkcenterData(workcenterData);
      const sqlStartTime = Date.now();
      await this.workcenterRepository.upsert(
        { ...transformedData, updatedAt: () => 'SYSUTCDATETIME()' }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['plant', 'workcenterId'] },
      );
      if (this.eventhubService.topicWorkcenterUpdates) {
        await this.publishMessageService.publishMessage(
          this.eventhubService.topicWorkcenterUpdates,
          {
            plant: transformedData.plant,
            workcenterId: transformedData.workcenterId,
          },
        );
      }
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'workcenter',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'workcenter',
      );
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base and publish message : ${error.message}`,
        this.context,
        error,
      );
    }
    return undefined;
  }

  @OnEvent('workcenter.u')
  private async updateByWorkcenterIdAndPlant(
    payload: Workcenter,
  ): Promise<void> {
    this.context.method = 'updateByWorkcenterIdAndPlant';
    if (!payload) {
      this.customLogger.error('Payload is empty', this.context);
      return;
    }

    const { workcenterId, plant, tableChangeLog, ...workcenterData } = payload;

    if (!workcenterId || !plant) {
      this.customLogger.error(
        'Invalid payload: missing workcenterId or plant',
        this.context,
      );
      return;
    }

    try {
      const transformedData =
        WorkcenterService.transformWorkcenterData(workcenterData);
      const sqlStartTime = Date.now();
      await this.workcenterRepository.upsert(
        {
          plant,
          workcenterId,
          ...transformedData,
          updatedAt: () => 'SYSUTCDATETIME()',
        }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['plant', 'workcenterId'] },
      );

      // Publish workcenter message outside the transaction
      if (this.eventhubService.topicWorkcenterUpdates) {
        await this.publishMessageService.publishMessage(
          this.eventhubService.topicWorkcenterUpdates,
          {
            plant,
            workcenterId,
          },
        );
      }
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'workcenter',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'workcenter',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating workcenter: ${error.message}`,
        this.context,
      );
    }
  }

  @OnEvent('workcenter.r')
  private async readSnapshot(payload: Workcenter): Promise<void> {
    this.context.method = 'readSnapshot';
    if (!payload)
      return this.customLogger.error(
        `payload is empty${payload}`,
        this.context,
      );

    const { workcenterId, plant, tableChangeLog, ...workcenterData } = payload;

    if (!workcenterId || !plant) {
      this.customLogger.error(
        'Invalid payload: missing workcenterId or plant',
        this.context,
      );
      return undefined;
    }
    try {
      const transformedData =
        WorkcenterService.transformWorkcenterData(workcenterData);
      const sqlStartTime = Date.now();
      await this.workcenterRepository.upsert(
        {
          plant,
          workcenterId,
          ...transformedData,
          updatedAt: () => 'SYSUTCDATETIME()',
        }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['plant', 'workcenterId'] },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'workcenter',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plant),
        'workcenter',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating workcenter: ${error.message}`,
        this.context,
      );
    }
    return undefined;
  }
}

