import { IdocMappingConfig } from '@/idoc/common/helpers/idoc-mapper-engine';

/**
 * LOIWCS v3 layout: ZMII_E1CRHDL is nested under E1CRHDL, or absent entirely.
 * Matches when E1CRHDL contains ZMII_E1CRHDL, or when ZMII_E1CRHDL is not at IDOC root.
 */
export const LOIWCS_V3_CONFIG: IdocMappingConfig = {
  id: 'LOIWCS::v3',
  matches: (idoc) => {
    const content = idoc['E1CRHDL'];
    const headerNode = (Array.isArray(content) ? content[0] : content) as
      | Record<string, unknown>
      | undefined;
    return (
      headerNode?.['ZMII_E1CRHDL'] !== undefined ||
      idoc['ZMII_E1CRHDL'] === undefined
    );
  },
  segments: [
    {
      path: 'EDI_DC40',
      fields: [
        { source: 'SNDPOR', target: 'erpSource', transforms: ['erpSource'] },
      ],
    },
    {
      path: 'E1CRHDL',
      fields: [
        { source: 'ARBPL', target: 'code', transforms: ['trim'] },
        { source: 'WERKS', target: 'plant' },
        { source: 'OBJID', target: 'sapObjectId' },
        {
          source: 'PARV6',
          target: 'costCenter',
          targetGroup: 'properties',
        },
        {
          source: 'VGWTS',
          target: 'stdValueKey',
          targetGroup: 'properties',
        },
      ],
    },
    {
      path: 'E1CRHDL.ZMII_E1CRHDL',
      fields: [{ source: 'VERWE', target: 'equipmentLevel' }],
    },
    {
      path: 'E1CRHDL.E1CRTXL',
      array: 'firstWithProp',
      arrayProp: 'KTEXT',
      fields: [{ source: 'KTEXT', target: 'description' }],
    },
  ],
};

/**
 * LOIWCS v2 layout: ZMII_E1CRHDL is at IDOC root level (not nested under E1CRHDL).
 * Matches when ZMII_E1CRHDL is present at IDOC root.
 */
export const LOIWCS_V2_CONFIG: IdocMappingConfig = {
  id: 'LOIWCS::v2',
  matches: (idoc) => idoc['ZMII_E1CRHDL'] !== undefined,
  segments: [
    {
      path: 'EDI_DC40',
      fields: [
        { source: 'SNDPOR', target: 'erpSource', transforms: ['erpSource'] },
      ],
    },
    {
      path: 'E1CRHDL',
      fields: [
        { source: 'ARBPL', target: 'code', transforms: ['trim'] },
        { source: 'WERKS', target: 'plant' },
        { source: 'OBJID', target: 'sapObjectId' },
        {
          source: 'PARV6',
          target: 'costCenter',
          targetGroup: 'properties',
        },
        {
          source: 'VGWTS',
          target: 'stdValueKey',
          targetGroup: 'properties',
        },
      ],
    },
    {
      path: 'ZMII_E1CRHDL',
      fields: [{ source: 'VERWE', target: 'equipmentLevel' }],
    },
    {
      path: 'E1CRTXL',
      array: 'firstWithProp',
      arrayProp: 'KTEXT',
      fields: [{ source: 'KTEXT', target: 'description' }],
    },
  ],
};

/**
 * LOIRNH v1 direct layout: E1CRHSL segments are directly under the IDOC node.
 * Matches when E1CRHSL is present at IDOC root.
 * Excludes SAP root nodes (parentObjectId = '00000000') which have no parent in our hierarchy.
 */
export const LOIRNH_V1_DIRECT_CONFIG: IdocMappingConfig = {
  id: 'LOIRNH::v1-direct',
  matches: (idoc) => idoc['E1CRHSL'] !== undefined,
  excludeWhen: [{ field: 'parentObjectId', value: '00000000' }],
  segments: [
    {
      path: 'E1CRHSL',
      array: 'all',
      fields: [
        { source: 'OBJID_HO', target: 'childObjectId' },
        { source: 'OBJID_UP', target: 'parentObjectId' },
      ],
    },
  ],
};

/**
 * LOIRNH v1 wrapped layout: E1CRHHL[] wrappers each contain E1CRHSL[] children.
 * Matches when E1CRHHL is present at IDOC root.
 * The engine auto-flattens the nested array path E1CRHHL.E1CRHSL.
 * Excludes SAP root nodes (parentObjectId = '00000000').
 */
export const LOIRNH_V1_WRAPPED_CONFIG: IdocMappingConfig = {
  id: 'LOIRNH::v1-wrapped',
  matches: (idoc) => idoc['E1CRHHL'] !== undefined,
  excludeWhen: [{ field: 'parentObjectId', value: '00000000' }],
  segments: [
    {
      path: 'E1CRHHL.E1CRHSL',
      array: 'all',
      fields: [
        { source: 'OBJID_HO', target: 'childObjectId' },
        { source: 'OBJID_UP', target: 'parentObjectId' },
      ],
    },
  ],
};
/**
 * MDM Equipment save replica
 * Matches when E1BP_IEQM_EXTRACTOR segment is present (contains EQUIPMENT_INT).
 */
export const MDM_EQUIPMENT_SAVEREPLICA_CONFIG: IdocMappingConfig = {
  id: 'MDM_EQUIPMENT::savereplica',
  matches: (idoc) => idoc['E1BP_IEQM_EXTRACTOR'] !== undefined,
  segments: [
    {
      path: 'EDI_DC40',
      fields: [
        { source: 'SNDPOR', target: 'erpSource', transforms: ['erpSource'] },
      ],
    },
    {
      path: 'E1BP_IEQM_EXTRACTOR',
      fields: [
        {
          source: 'EQUIPMENT_INT',
          target: 'code',
          transforms: ['trim', 'removeLeadingZeros'],
        },
        { source: 'DESCRIPT', target: 'description' },
        { source: 'PLANPLANT', target: 'plant' },
        { source: 'READ_FLOC', target: 'physicalAssetLocation' },
        { source: 'FREE_NUM1', target: 'freeNum1' },
      ],
    },
  ],
};

import { ReceivedEventData } from '@azure/event-hubs';
import { BlobCheckpointStore } from '@azure/eventhubs-checkpointstore-blob';
import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '@/shared/logger/app-logger';

export interface CheckpointConfig {
  consumerGroup: string;
  eventHubName: string;
  eventHubNamespace: string;
  checkpointInterval: number;
}

export interface PartitionInfo {
  partitionId: string;
  lastCheckpointTime: number;
  lastProcessedEvent?: ReceivedEventData;
}

/**
 * Create log context for checkpoint operations
 * @param method Method name
 * @param partitionId Partition ID (optional)
 * @param sequenceNumber Sequence number (optional)
 * @returns JobsLogContext
 */
function createLogContext(
  method: string,
  partitionId?: string,
  sequenceNumber?: number,
): JobsLogContext {
  return {
    method,
    object: partitionId,
    plant: sequenceNumber,
    service: 'EventHubCheckpoint',
  };
}

/**
 * Create checkpoint payload for updating checkpoint store
 * @param config Configuration for the checkpoint including consumer group, event hub name, namespace, and interval.
 * @param partitionId The ID of the partition for which the checkpoint is being created.
 * @param event The event data received from the Event Hub.
 * @returns An object containing checkpoint information to update the checkpoint store.
 */
export function createCheckpointPayload(
  config: CheckpointConfig,
  partitionId: string,
  event: ReceivedEventData,
): {
  consumerGroup: string;
  eventHubName: string;
  fullyQualifiedNamespace: string;
  offset: string;
  partitionId: string;
  sequenceNumber: number;
} {
  return {
    consumerGroup: config.consumerGroup,
    eventHubName: config.eventHubName,
    fullyQualifiedNamespace: `${config.eventHubNamespace}.servicebus.windows.net`,
    offset: event.offset,
    partitionId,
    sequenceNumber: event.sequenceNumber,
  };
}

/**
 * Perform final checkpoint for a partition
 * @param checkpointStore Blob checkpoint store
 * @param config Checkpoint configuration
 * @param partitionInfo Partion Info
 * @param partitionId Partition ID
 * @param event Event data
 * @param logger Application logger
 */
export async function updateCheckpointIfNeeded(
  checkpointStore: BlobCheckpointStore,
  config: CheckpointConfig,
  partitionInfo: Map<string, PartitionInfo>,
  partitionId: string,
  event: ReceivedEventData,
  logger: AppLogger,
): Promise<void> {
  const partInfo = partitionInfo.get(partitionId);
  if (!partInfo) {
    return;
  }

  const now = Date.now();
  const timeSinceLastCheckpoint = now - partInfo.lastCheckpointTime;

  if (timeSinceLastCheckpoint >= config.checkpointInterval) {
    const context = createLogContext(
      'updateCheckpointIfNeeded',
      partitionId,
      event.sequenceNumber,
    );

    try {
      const checkpointPayload = createCheckpointPayload(
        config,
        partitionId,
        event,
      );
      await checkpointStore.updateCheckpoint(checkpointPayload);

      // Update partition info
      partitionInfo.set(partitionId, {
        ...partInfo,
        lastCheckpointTime: now,
      });

      logger.debug('Checkpoint updated for partition', context);
    } catch (error) {
      logger.error(
        `Error updating checkpoint for partition ${partitionId}: ${error.message}`,
        context,
        error.stack,
      );
    }
  }
}

/**
 * Perform final checkpoint for a partition
 * @param checkpointStore Blob checkpoint store
 * @param config Checkpoint configuration
 * @param partitionId Partition ID
 * @param event Event data
 * @param logger Application logger
 */
export async function performFinalCheckpoint(
  checkpointStore: BlobCheckpointStore,
  config: CheckpointConfig,
  partitionId: string,
  event: ReceivedEventData,
  logger: AppLogger,
): Promise<void> {
  const context = createLogContext(
    'performFinalCheckpoint',
    partitionId,
    event.sequenceNumber,
  );

  try {
    const checkpointPayload = createCheckpointPayload(
      config,
      partitionId,
      event,
    );
    await checkpointStore.updateCheckpoint(checkpointPayload);

    logger.debug('Final checkpoint completed for partition', context);
  } catch (error) {
    logger.error(
      `Error during final checkpoint for partition ${partitionId}: ${error.message}`,
      context,
      error.stack,
    );
  }
}

/**
 * Perform final checkpoints for all partitions before shutdown
 * @param checkpointStore Blob checkpoint store
 * @param config Checkpoint configuration
 * @param partitionInfo Map of partition information
 * @param logger Application logger
 */
export async function performFinalCheckpoints(
  checkpointStore: BlobCheckpointStore,
  config: CheckpointConfig,
  partitionInfo: Map<string, PartitionInfo>,
  logger: AppLogger,
): Promise<void> {
  const context = createLogContext('performFinalCheckpoints');

  logger.log('Performing final checkpoints before shutdown', context);

  const checkpointPromises = [...partitionInfo.entries()]
    .filter(([, info]) => info.lastProcessedEvent !== undefined)
    .map(([partitionId, info]) => {
      const lastEvent = info.lastProcessedEvent;
      if (!lastEvent) {
        return Promise.resolve();
      }
      return performFinalCheckpoint(
        checkpointStore,
        config,
        partitionId,
        lastEvent,
        logger,
      );
    });

  await Promise.all(checkpointPromises);
}

import { JobsLogContext } from '@mesx/common-lib';
import { EventHubClients, initializeEventHub } from './initialization';
import { EventHubSdkConfig } from '@/idoc/config/eventhub-sdk/eventhub-sdk-config.interface';
import { AppLogger } from '@/shared/logger/app-logger';
import { exponentialBackoffRetry } from '@/shared/utils/exponential-backoff-retry';

/**
 * Create log context for error recovery operations
 * @param method Method name
 * @param serviceName Service name
 * @returns JobsLogContext
 */
function createLogContext(method: string, serviceName: string): JobsLogContext {
  return {
    method,
    service: serviceName,
  };
}

/**
 * Attempt to reconnect to EventHub after an error
 * @param config EventHub configuration
 * @param logger Application logger
 * @param serviceName Service name
 * @param isShuttingDown Flag indicating if service is shutting down
 * @param isShuttingDown.value Value
 * @param onReconnected Callback when reconnection is successful
 */
export async function attemptReconnect(
  config: EventHubSdkConfig,
  logger: AppLogger,
  serviceName: string,
  isShuttingDown: { value: boolean },
  onReconnected: (clients: EventHubClients) => Promise<void>,
): Promise<void> {
  const context = createLogContext('attemptReconnect', serviceName);

  try {
    if (isShuttingDown.value) {
      logger.log(
        'Service is shutting down, skipping reconnection attempt',
        context,
      );
      return;
    }

    logger.log(
      'Attempting to reconnect to EventHub with exponential backoff...',
      context,
    );

    await exponentialBackoffRetry(
      logger,
      context,
      async () => {
        if (isShuttingDown.value) {
          return;
        }

        const clients = await initializeEventHub(config, logger);

        if (isShuttingDown.value) {
          try {
            await clients.consumerClient.close();
          } catch {
            // Ignore cleanup errors during shutdown
          }
          return;
        }

        await onReconnected(clients);
        logger.log('Successfully reconnected to EventHub', context);
      },
      10,
      5000,
      true,
      1,
      60,
      () => !isShuttingDown.value,
    );
  } catch (error) {
    const normalizedError = error as Error;
    logger.error(
      `Failed to reconnect to EventHub: ${normalizedError.message}`,
      context,
      normalizedError,
    );
  }
}

import { EventHubConsumerClient } from '@azure/event-hubs';
import { BlobCheckpointStore } from '@azure/eventhubs-checkpointstore-blob';
import { DefaultAzureCredential } from '@azure/identity';
import { ContainerClient, BlobServiceClient } from '@azure/storage-blob';
import { JobsLogContext } from '@mesx/common-lib';
import { EventHubSdkConfig } from '@/idoc/config/eventhub-sdk/eventhub-sdk-config.interface';
import { AppLogger } from '@/shared/logger/app-logger';

export interface EventHubClients {
  consumerClient: EventHubConsumerClient;
  checkpointStore: BlobCheckpointStore;
  containerClient: ContainerClient;
}

/**
 * Create log context for EventHub initialization operations
 * @param method Method name
 * @param eventHubName EventHub name (optional)
 * @returns JobsLogContext
 */
function createLogContext(
  method: string,
  eventHubName?: string,
): JobsLogContext {
  return {
    method,
    object: eventHubName,
    service: 'EventHubInitialization',
  };
}

/**
 * Initialize EventHub consumer client and checkpoint store
 * @param config EventHub configuration
 * @param logger Application logger
 * @returns Promise<EventHubClients> Initialized EventHub clients
 */
export async function initializeEventHub(
  config: EventHubSdkConfig,
  logger: AppLogger,
): Promise<EventHubClients> {
  const context = createLogContext('initializeEventHub', config.eventHubName);

  const credential = new DefaultAzureCredential();

  // Initialize blob storage for checkpointing
  const blobServiceClient = new BlobServiceClient(
    `https://${config.storageAccountName}.blob.core.windows.net`,
    credential,
  );

  const containerClient = blobServiceClient.getContainerClient(
    config.checkpointContainerName,
  );

  await containerClient.createIfNotExists();
  const checkpointStore = new BlobCheckpointStore(containerClient);

  // Create EventHub consumer client
  const fullyQualifiedNamespace = `${config.eventHubNamespace}.servicebus.windows.net`;

  const consumerClient = new EventHubConsumerClient(
    config.consumerGroup,
    fullyQualifiedNamespace,
    config.eventHubName,
    credential,
    checkpointStore,
    {
      retryOptions: {
        retryDelayInMs: 1000,
        maxRetryDelayInMs: 15_000,
      },
    },
  );

  logger.log(`EventHub initialized for ${config.eventHubName}`, context);

  return {
    consumerClient,
    checkpointStore,
    containerClient,
  };
}

/**
 * Clean up EventHub resources
 * @param clients EventHub clients to clean up
 * @param logger Application logger
 */
export async function cleanupEventHub(
  clients: EventHubClients,
  logger: AppLogger,
): Promise<void> {
  const context = createLogContext('cleanupEventHub');

  try {
    logger.log('Cleaning up EventHub resources', context);

    await clients.consumerClient.close();

    logger.log('EventHub cleanup completed', context);
  } catch (error) {
    logger.error(
      `Error during EventHub cleanup: ${error.message}`,
      context,
      error.stack,
    );
  }
}

import { ReceivedEventData, PartitionContext } from '@azure/event-hubs';
import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { ShutdownState } from './shutdown';
import { AppLogger } from '@/shared/logger/app-logger';

export interface MessageProcessor<T = unknown> {
  processMessage: (
    message: T,
    sequenceNumber: string,
    partitionId?: string,
  ) => Promise<void>;
}

export interface ProcessingConfig {
  serviceName: string;
  topicName?: string;
}

/**
 * Result of message processing
 */
export interface ProcessingResult {
  status: 'processed' | 'sql' | 'filtered';
  plantCode?: string;
}

/**
 * Enhanced message processor with processing result
 */
export interface EnhancedMessageProcessor<T = unknown> {
  processMessage: (
    message: T,
    sequenceNumber: string,
    partitionId?: string,
  ) => Promise<ProcessingResult | void>;
}
export interface HandleEventBatch {
  events: Array<ReceivedEventData>;
  partitionContext: PartitionContext;
  config: ProcessingConfig;
  logger: AppLogger;
  onEventProcessed?: (partitionId: string, event: ReceivedEventData) => void;
  shutdownState?: ShutdownState;
}

/**
 * Create log context for message processing operations
 * @param method Method name
 * @param serviceName Service name
 * @param sequenceNumber Sequence number (optional)
 * @param partitionId Partition ID (optional)
 * @returns JobsLogContext
 */
function createLogContext(
  method: string,
  serviceName: string,
  sequenceNumber?: string,
  partitionId?: string,
): JobsLogContext {
  return {
    method,
    object: sequenceNumber,
    plant: partitionId ? Number(partitionId) : undefined,
    service: serviceName,
  };
}

/**
 * Process a single event with validation, masking, and error handling
 * @param event Event to process
 * @param processor Message processor
 * @param config Processing configuration
 * @param logger Application logger
 * @param partitionId Partition ID of the event
 * @param shutdownState Optional shutdown state for cancellation
 */
export async function processSingleEvent<T>(
  event: ReceivedEventData,
  processor: MessageProcessor<T>,
  config: ProcessingConfig,
  logger: AppLogger,
  partitionId: string,
  shutdownState?: ShutdownState,
): Promise<void> {
  const sequenceNumber = String(event.sequenceNumber);
  const startContext = createLogContext(
    'processSingleEvent',
    config.serviceName,
    sequenceNumber,
  );
  // Extract message and plantCode for RECEIVED tracking
  const message = event.body as T;
  const messageWithPlant = message as Record<string, unknown>;

  // Safely extract plant code - only convert if it's a primitive value
  let plantCode: string | undefined;
  if (
    messageWithPlant?.PLANT !== undefined &&
    messageWithPlant?.PLANT !== null
  ) {
    const plantValue = messageWithPlant.PLANT;
    if (typeof plantValue === 'string' || typeof plantValue === 'number') {
      plantCode = String(plantValue);
    }
  }

  // Track RECEIVED metric immediately (all events received from EventHub)
  if (config.topicName) {
    try {
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.RECEIVED,
        plantCode,
        config.topicName,
        partitionId,
      );
    } catch {
      // Silent fail - don't break processing if telemetry fails
    }
  }

  // Skip processing if service is shutting down
  if (shutdownState?.value) {
    logger.debug(
      `Skipping event ${sequenceNumber} processing - service is shutting down`,
      startContext,
    );
    return;
  }

  try {
    logger.debug(
      `============== ${sequenceNumber} Start processing event =======================`,
      startContext,
    );

    // Process the message
    await processor.processMessage(message, sequenceNumber, partitionId);

    const successContext = createLogContext(
      'processMessage',
      config.serviceName,
      sequenceNumber,
    );
    logger.debug(
      `Successfully processed event with sequence number ${sequenceNumber}`,
      successContext,
    );
  } catch (error) {
    const errorContext = createLogContext(
      'processSingleEvent',
      config.serviceName,
      sequenceNumber,
    );
    logger.error(
      `Error processing event with sequence number ${sequenceNumber}: ${error.message}`,
      errorContext,
      error.stack,
    );
  } finally {
    const endContext = createLogContext(
      'processSingleEvent',
      config.serviceName,
      sequenceNumber,
    );
    logger.debug(
      `============== ${sequenceNumber} END processing event =======================`,
      endContext,
    );
  }
}

/**
 * Handle a batch of events from EventHub with concurrency control
 * @param processor Message processor
 * @param handleEventBatchInterface Object containing batch handling parameters and dependencies
 */
export async function handleEventBatch<T>(
  processor: MessageProcessor<T>,
  handleEventBatchInterface: HandleEventBatch,
): Promise<void> {
  const {
    config,
    events,
    logger,
    partitionContext,
    onEventProcessed,
    shutdownState,
  } = handleEventBatchInterface;
  if (events.length === 0) {
    return;
  }

  const batchContext = createLogContext(
    'handleEventBatch',
    config.serviceName,
    undefined,
    partitionContext.partitionId,
  );

  logger.debug(
    `Processing ${events.length} events from partition ${partitionContext.partitionId}`,
    batchContext,
  );

  // Note: it is not necessary to implement the lock as when it is processing it is done in a serialized way for each partition.”
  for (const event of events) {
    // Skip if shutting down
    if (shutdownState?.value) {
      return;
    }

    await processSingleEvent(
      event,
      processor,
      config,
      logger,
      partitionContext.partitionId,
      shutdownState,
    );

    // Notify that event was processed (for checkpoint tracking)
    if (!shutdownState?.value && onEventProcessed) {
      onEventProcessed(partitionContext.partitionId, event);
    }
  }
}

/**
 * Handle errors from EventHub processing
 * @param error Error that occurred
 * @param partitionContext Partition context
 * @param serviceName Service name
 * @param logger Application logger
 * @param onError Optional error callback
 */
export function handleEventHubError(
  error: Error,
  partitionContext: PartitionContext | undefined,
  serviceName: string,
  logger: AppLogger,
  onError?: (error: Error) => void,
): void {
  const partitionId = partitionContext?.partitionId ?? 'unknown';
  const errorContext = createLogContext(
    'handleEventHubError',
    serviceName,
    undefined,
    partitionId,
  );

  logger.error(
    `Error in EventHub consumer for partition ${partitionId}: ${error.message}`,
    errorContext,
    error,
  );

  // Allow custom error handling
  if (onError) {
    onError(error);
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '@/shared/logger/app-logger';

/**
 * Create log context for shutdown operations
 * @param method Method name
 * @param serviceName Service name
 * @returns JobsLogContext
 */
function createLogContext(method: string, serviceName: string): JobsLogContext {
  return {
    method,
    service: serviceName,
  };
}

/**
 * Shared shutdown state that can be passed by reference
 */
export interface ShutdownState {
  value: boolean;
}

/**
 * Create a new shutdown state object
 * @returns ShutdownState
 */
export function createShutdownState(): ShutdownState {
  return { value: false };
}

/**
 * Set shutdown state and log the status
 * @param state Shutdown state object
 * @param logger Application logger
 * @param serviceName Service name
 */
export function initiateShutdown(
  state: ShutdownState,
  logger: AppLogger,
  serviceName: string,
): void {
  const context = createLogContext('initiateShutdown', serviceName);

  if (state.value) {
    logger.log('Shutdown already initiated', context);
    return;
  }
  const stateAlias = state;
  stateAlias.value = true;
  logger.log('Shutdown initiated', context);
}

/**
 * Check if service is in shutdown state
 * @param state Shutdown state object
 * @returns boolean True if service is shutting down
 */
export function isShuttingDown(state: ShutdownState): boolean {
  return state.value;
}

import {
  ReceivedEventData,
  Subscription,
  PartitionContext,
} from '@azure/event-hubs';
import { JobsLogContext } from '@mesx/common-lib';
import {
  CheckpointConfig,
  PartitionInfo,
  updateCheckpointIfNeeded,
} from './checkpoint';
import { attemptReconnect } from './error-recovery';
import { EventHubClients } from './initialization';
import {
  MessageProcessor,
  ProcessingConfig,
  handleEventBatch,
  handleEventHubError,
} from './message-processing';
import { ShutdownState } from './shutdown';
import { EventHubSdkConfig } from '@/idoc/config/eventhub-sdk/eventhub-sdk-config.interface';
import { AppLogger } from '@/shared/logger/app-logger';

/**
 * Configuration for EventHub subscription
 * Defines optional configuration for EventHub subscriptions
 */
export interface SubscriptionConfig {
  /** Whether to enable automatic checkpointing */
  enableCheckpointing?: boolean;
  /** Maximum batch size for event processing */
  maxBatchSize?: number;
}

/**
 * Configuration for error recovery
 * Defines settings for handling EventHub connection errors and recovery logic
 */
export interface ErrorRecoveryConfig {
  /** Whether error recovery is enabled */
  enabled: boolean;
  /** EventHub SDK configuration for reconnection attempts */
  eventHubConfig: EventHubSdkConfig;
}

/**
 * Result of subscription to EventHub
 * Contains the subscription object and partition tracking information
 */
export interface SubscriptionResult {
  /** The EventHub subscription object */
  subscription: Subscription;
  /** Map of partition IDs to their tracking information */
  partitionInfo: Map<string, PartitionInfo>;
}

/**
 * Parameters for the subscribeToEventHub function
 * Contains all the configuration needed to set up an EventHub subscription
 */
export interface SubscribeToEventHub {
  /** EventHub clients for connection and checkpointing */
  clients: EventHubClients;
  /** Configuration for message processing behavior */
  processingConfig: ProcessingConfig;
  /** Configuration for checkpoint behavior */
  checkpointConfig: CheckpointConfig;
  /** Configuration for subscription options */
  subscriptionConfig: SubscriptionConfig;
  /** Logger instance for operational logging */
  logger: AppLogger;
  /** Optional shutdown state tracking for graceful termination */
  shutdownState?: ShutdownState;
  /** Optional configuration for error recovery */
  errorRecoveryConfig?: ErrorRecoveryConfig;
}

/**
 * Creates a structured log context for subscription operations
 * @param method - The method name generating the log
 * @param serviceName - The name of the service handling the subscription
 * @param eventHubName - Optional EventHub name for additional context
 * @returns A structured log context object for consistent logging
 */
function createLogContext(
  method: string,
  serviceName: string,
  eventHubName?: string,
): JobsLogContext {
  return {
    method,
    object: eventHubName,
    service: serviceName,
  };
}

/**
 * Create the event processing handler
 * @param processor Message processor for the specific topic
 * @param partitionInfo Map to store partition-specific information
 * @param options Handler configuration options
 * @param options.clients EventHub clients for processing and checkpointing
 * @param options.checkpointConfig Configuration for checkpoint behavior
 * @param options.processingConfig Configuration for message processing
 * @param options.subscriptionConfig Configuration for the subscription
 * @param options.logger Logger instance for operational logging
 * @param options.shutdownState Optional shutdown state tracking
 * @returns Async function for processing event batches from EventHub
 */
function createProcessEventsHandler<T>(
  processor: MessageProcessor<T>,
  partitionInfo: Map<string, PartitionInfo>,
  options: {
    clients: EventHubClients;
    checkpointConfig: CheckpointConfig;
    processingConfig: ProcessingConfig;
    subscriptionConfig: SubscriptionConfig;
    logger: AppLogger;
    shutdownState?: ShutdownState;
  },
): (
  events: Array<ReceivedEventData>,
  partitionContext: PartitionContext,
) => Promise<void> {
  const {
    clients,
    checkpointConfig,
    processingConfig,
    subscriptionConfig,
    logger,
    shutdownState,
  } = options;

  return async (
    events: Array<ReceivedEventData>,
    partitionContext: PartitionContext,
  ): Promise<void> => {
    // Initialize partition info if not exists
    if (!partitionInfo.has(partitionContext.partitionId)) {
      partitionInfo.set(partitionContext.partitionId, {
        partitionId: partitionContext.partitionId,
        lastCheckpointTime: 0,
      });
    }

    await handleEventBatch(processor, {
      config: processingConfig,
      events,
      logger,
      onEventProcessed: (partitionId: string, event: ReceivedEventData) => {
        const partInfo = partitionInfo.get(partitionId);
        if (partInfo) {
          partitionInfo.set(partitionId, {
            ...partInfo,
            lastProcessedEvent: event,
          });
        }

        if (subscriptionConfig.enableCheckpointing !== false) {
          updateCheckpointIfNeeded(
            clients.checkpointStore,
            checkpointConfig,
            partitionInfo,
            partitionId,
            event,
            logger,
          );
        }
      },
      partitionContext,
      shutdownState,
    });
  };
}

/**
 * Create the error processing handler
 * @param options Handler configuration options
 * @param options.processingConfig Configuration for message processing
 * @param options.logger Logger instance for error logging
 * @param options.errorRecoveryConfig Optional configuration for error recovery
 * @param options.shutdownState Optional shutdown state for cancellation
 * @returns Async function for handling errors from EventHub
 */
function createProcessErrorHandler(options: {
  processingConfig: ProcessingConfig;
  logger: AppLogger;
  errorRecoveryConfig?: ErrorRecoveryConfig;
  shutdownState?: ShutdownState;
}): (error: Error, partitionContext?: PartitionContext) => Promise<void> {
  const { processingConfig, logger, errorRecoveryConfig, shutdownState } =
    options;

  return async (
    error: Error,
    partitionContext?: PartitionContext,
  ): Promise<void> => {
    handleEventHubError(
      error,
      partitionContext,
      processingConfig.serviceName,
      logger,
      // Add error recovery if enabled
      errorRecoveryConfig?.enabled && errorRecoveryConfig.eventHubConfig
        ? (): void => {
            // Only attempt reconnect if not shutting down
            if (!shutdownState?.value && errorRecoveryConfig.eventHubConfig) {
              attemptReconnect(
                errorRecoveryConfig.eventHubConfig,
                logger,
                processingConfig.serviceName,
                shutdownState || { value: false },
                async () => {
                  // This callback is called when reconnection is successful
                  logger.log(
                    'Successfully reconnected to EventHub, reinitializing subscription',
                    createLogContext('reconnect', processingConfig.serviceName),
                  );
                },
              );
            }
          }
        : undefined,
    );
  };
}

/**
 * Create the initialization handler for EventHub partitions
 * @param options Handler configuration options
 * @param options.logger Logger instance for initialization logging
 * @param options.processingConfig Configuration for message processing
 * @param options.checkpointConfig Configuration for checkpoint behavior
 * @returns Async function called when a partition is initialized
 */
function createProcessInitializeHandler(options: {
  logger: AppLogger;
  processingConfig: ProcessingConfig;
  checkpointConfig: CheckpointConfig;
}): (partitionContext: PartitionContext) => Promise<void> {
  const { logger, processingConfig, checkpointConfig } = options;

  return async (partitionContext: PartitionContext): Promise<void> => {
    logger.debug(
      `Partition ${partitionContext.partitionId} has been initialized and assigned to this consumer instance`,
      createLogContext(
        'processInitialize',
        processingConfig.serviceName,
        checkpointConfig.eventHubName,
      ),
    );
  };
}

/**
 * Create the partition close handler
 * @param options Handler configuration options
 * @param options.logger Logger instance for closure logging
 * @param options.processingConfig Configuration for message processing
 * @param options.checkpointConfig Configuration for checkpoint behavior
 * @returns Async function called when a partition is closed/released
 */
function createProcessCloseHandler(options: {
  logger: AppLogger;
  processingConfig: ProcessingConfig;
  checkpointConfig: CheckpointConfig;
}): (reason: string, partitionContext: PartitionContext) => Promise<void> {
  const { logger, processingConfig, checkpointConfig } = options;

  return async (
    reason: string,
    partitionContext: PartitionContext,
  ): Promise<void> => {
    logger.debug(
      `Partition ${partitionContext.partitionId} has been released from this consumer instance. Reason: ${reason}`,
      createLogContext(
        'processClose',
        processingConfig.serviceName,
        checkpointConfig.eventHubName,
      ),
    );
  };
}

/**
 * Subscription to EventHub with production features
 * @param processor Message processor for topic-specific message handling
 * @param subscribeToEventHubInterface Configuration interface containing all necessary components
 * @param subscribeToEventHubInterface.clients EventHub clients for connecting and checkpointing
 * @param subscribeToEventHubInterface.processingConfig Configuration for message processing
 * @param subscribeToEventHubInterface.checkpointConfig Configuration for checkpoint behavior
 * @param subscribeToEventHubInterface.subscriptionConfig Configuration for the subscription behavior
 * @param subscribeToEventHubInterface.logger Logger instance for operational logging
 * @param subscribeToEventHubInterface.shutdownState Optional shutdown state tracking
 * @param subscribeToEventHubInterface.errorRecoveryConfig Optional configuration for error recovery
 * @returns Subscription result containing subscription instance and partition info
 */
export function subscribeToEventHub<T>(
  processor: MessageProcessor<T>,
  subscribeToEventHubInterface: SubscribeToEventHub,
): SubscriptionResult {
  const {
    checkpointConfig,
    clients,
    logger,
    processingConfig,
    subscriptionConfig,
    errorRecoveryConfig,
    shutdownState,
  } = subscribeToEventHubInterface;
  const context = createLogContext(
    'subscribeToEventHub',
    processingConfig.serviceName,
    checkpointConfig.eventHubName,
  );

  const partitionInfo = new Map<string, PartitionInfo>();

  // Create handlers using the extracted helper functions
  const processEventsHandler = createProcessEventsHandler(
    processor,
    partitionInfo,
    {
      checkpointConfig,
      clients,
      logger,
      processingConfig,
      shutdownState,
      subscriptionConfig,
    },
  );

  const processErrorHandler = createProcessErrorHandler({
    processingConfig,
    logger,
    errorRecoveryConfig,
    shutdownState,
  });

  const processInitializeHandler = createProcessInitializeHandler({
    logger,
    processingConfig,
    checkpointConfig,
  });

  const processCloseHandler = createProcessCloseHandler({
    logger,
    processingConfig,
    checkpointConfig,
  });

  // Much cleaner subscription call with extracted handlers
  const subscription = clients.consumerClient.subscribe(
    {
      processEvents: processEventsHandler,
      processError: processErrorHandler,
      processInitialize: processInitializeHandler,
      processClose: processCloseHandler,
    },
    {
      maxBatchSize: subscriptionConfig.maxBatchSize ?? 1,
    },
  );

  logger.log(
    `Subscribed to EventHub ${checkpointConfig.eventHubName} with enhanced features`,
    context,
  );

  return {
    subscription,
    partitionInfo,
  };
}

/**
 * Unsubscribes from an EventHub subscription and logs the outcome
 * @param subscription - The EventHub subscription to close
 * @param serviceName - The name of the service for logging context
 * @param logger - Logger instance for operational logging
 * @returns Promise that resolves when unsubscription is complete
 */
export async function unsubscribeFromEventHub(
  subscription: Subscription,
  serviceName: string,
  logger: AppLogger,
): Promise<void> {
  const context = createLogContext('unsubscribeFromEventHub', serviceName);

  try {
    logger.log('Unsubscribing from EventHub', context);

    await subscription.close();

    logger.log('Successfully unsubscribed from EventHub', context);
  } catch (error) {
    logger.error(
      `Error unsubscribing from EventHub: ${error.message}`,
      context,
      error,
    );
  }
}

export class IdocHandlerHelpers {
  /**
   * Cast a ParsedIdocValue to a ParsedIdoc object, or return undefined.
   * @param value - The value to cast; expected to be an unknown payload.
   * @returns The value cast as a plain object, or `undefined` if it is not an object.
   */
  public static getNode(value: unknown): Record<string, unknown> | undefined {
    return typeof value === 'object' && value !== null && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : undefined;
  }

  /**
   * Resolve the IDOC node from any payload shape:
   *   - Direct:  `{ IDOC: { … } }`
   *   - Wrapped: `{ ZLOIWCS3: { IDOC: { … } } }`
   *   - Fallback: return the root itself
   * @param parsedIdoc - The parsed IDOC payload object to resolve the IDOC node from.
   * @returns The resolved IDOC node as a plain object.
   */
  public static getIdocNode(
    parsedIdoc: Record<string, unknown>,
  ): Record<string, unknown> {
    const directIdoc = IdocHandlerHelpers.getNode(parsedIdoc['IDOC']);
    if (directIdoc) {
      return directIdoc;
    }

    const rootKey = Object.keys(parsedIdoc).find((key) => !key.startsWith('@'));
    if (!rootKey) {
      return parsedIdoc;
    }

    const rootNode = IdocHandlerHelpers.getNode(parsedIdoc[rootKey]);
    if (!rootNode) {
      return parsedIdoc;
    }

    return IdocHandlerHelpers.getNode(rootNode['IDOC']) ?? rootNode;
  }
}

import { parseSapDate } from './sap-date.helper';

/** Built-in transform identifiers */
export type TransformId =
  | 'trim'
  | 'sapDate'
  | 'float'
  | 'int'
  | 'erpSource'
  | 'uppercase'
  | 'lowercase'
  | 'removeLeadingZeros';

/**
 * A single field extraction rule.
 *
 * The engine resolves the value in this priority:
 *   1. `value`       → static literal
 *   2. `fromContext`  → injected from context map
 *   3. `source`      → read from the resolved segment node
 */
export interface FieldRule {
  /** Field name in the source segment (omit when using `value` or `fromContext`) */
  source?: string;
  /** Target field name in the output object */
  target: string;
  /** Ordered transforms to apply */
  transforms?: Array<TransformId>;
  /** Static value (overrides source) */
  value?: unknown;
  /** Inject from a context key */
  fromContext?: string;
  /** Default when resolved value is undefined/null */
  defaultValue?: unknown;
  /**
   * If set, the resolved value is merged into `output[targetGroup][target]`
   * instead of directly into `output[target]`.
   * Use this to produce a nested properties object at mapping time.
   * e.g. targetGroup: 'properties' → output.properties.costcenter = value
   */
  targetGroup?: string;
}

/**
 * Describes how to extract data from one IDoc segment.
 *
 * `path`:  dot-separated navigation from the IDOC node.
 *          e.g. "E1CRHDL.E1CRTXL" → idoc['E1CRHDL']['E1CRTXL']
 *          e.g. "EDI_DC40"         → idoc['EDI_DC40']
 *
 * `array`: How to handle the resolved node if it's an array.
 *          - omitted / undefined → treat as single object
 *          - 'first'            → take first element
 *          - 'firstWithProp'    → take first element where `arrayProp` is truthy
 *          - 'all'              → produce one output per element (repeating segment)
 *
 * `fields`: Extraction rules for this segment's fields.
 */
export interface SegmentRule {
  /** Dot-path from IDOC root to the segment */
  path: string;
  /** Field extraction rules */
  fields: Array<FieldRule>;
  /** Array handling strategy */
  array?: 'first' | 'firstWithProp' | 'all';
  /** Property name for 'firstWithProp' strategy */
  arrayProp?: string;
  /** Sub-property to extract after array pick (e.g. 'KTEXT' from picked E1CRTXL element) */
  arrayItemSubPath?: string;
}

/**
 * Complete mapping configuration for one IDoc type+version.
 * This is what each handler provides to the engine.
 */
export interface IdocMappingConfig {
  /** Human-readable identifier (e.g. 'LOIWCS::v3', 'LOIRNH::v1') */
  id: string;
  /**
   * Predicate evaluated against the unwrapped IDOC node.
   * When present, the handler selects the first config for which this returns true.
   * Omit to make the config an unconditional fallback.
   */
  matches?: (idoc: Record<string, unknown>) => boolean;
  /**
   * Segment rules — processed in order.
   * Rules with `array: 'all'` produce multiple outputs (repeating segments).
   */
  segments: Array<SegmentRule>;
  /**
   * Post-extraction record filter.
   * Any record where `record[field] === value` for at least one entry is excluded.
   * e.g. `[{ field: 'parentObjectId', value: '00000000' }]` removes SAP root nodes.
   */
  excludeWhen?: Array<{ field: string; value: unknown }>;
}

// ---------------------------------------------------------------------------
// Transform registry
// ---------------------------------------------------------------------------

const TRANSFORMS: Record<TransformId, (input: unknown) => unknown> = {
  /**
   * Normalises an IDoc SNDPOR sender-port value to a 3-char ERP source identifier.
   * Convention: SNDPOR = "SAP" + <3-char system ID>, e.g. "SAPTC2" → "TC2".
   * Falls back to the trimmed 3-char prefix when the "SAP" prefix is absent.
   * @param v - The raw SNDPOR value to normalise.
   * @returns Normalised ERP source identifier (e.g. "TC2"), or original value when not a string.
   */
  erpSource: (v) => {
    if (typeof v !== 'string') return v;
    const upper = v.trim().toUpperCase();
    if (upper.startsWith('SAP') && upper.length > 3) return upper.slice(3, 6);
    return upper.slice(0, 3);
  },
  float: (v) =>
    typeof v === 'string' ? Number.parseFloat(v.trim()) || undefined : v,
  int: (v) =>
    typeof v === 'string' ? Number.parseInt(v.trim(), 10) || undefined : v,

  lowercase: (v) => (typeof v === 'string' ? v.toLowerCase() : v),
  removeLeadingZeros: (v) =>
    typeof v === 'string' && /^\d+$/.test(v) ? v.replace(/^0+/, '') : v,
  sapDate: (v) => (typeof v === 'string' ? parseSapDate(v) : v),

  trim: (v) => (typeof v === 'string' ? v.trim() : v),
  uppercase: (v) => (typeof v === 'string' ? v.toUpperCase() : v),
};

/**
 * Normalize a value that may be a single object or an array into an array.
 * @param value - The value to normalize; may be a single item, an array, or undefined.
 * @returns An array containing the provided item(s), or an empty array if the value is undefined or null.
 */
export function normalizeToArray<T>(value: T | Array<T> | undefined): Array<T> {
  if (Array.isArray(value)) return value;
  if (value !== undefined && value !== null) return [value];
  return [];
}

/**
 * Traverse a nested object by a dot-separated path and return the value at that location.
 * When an intermediate node is an array, the remaining path is applied to each element
 * and the results are flattened — enabling wrapped segment layouts such as
 * `E1CRHHL[].E1CRHSL[]` to be addressed as `'E1CRHHL.E1CRHSL'`.
 * @param object - The root object to traverse.
 * @param path - Dot-separated key path (e.g. `"E1CRHDL.E1CRTXL"`).
 * @returns The value found at the given path, or `undefined` if any key is missing.
 */
function resolvePath(object: Record<string, unknown>, path: string): unknown {
  const keys = path.split('.');
  let current: unknown = object;

  for (let index = 0; index < keys.length; index += 1) {
    if (current === undefined || current === null) return undefined;

    if (Array.isArray(current)) {
      // Auto-flatten: apply remaining path to each array element and collect results.
      const remainingPath = keys.slice(index).join('.');
      const results = (current as Array<unknown>)
        .filter((item) => typeof item === 'object' && item !== null)
        .map((item) =>
          resolvePath(item as Record<string, unknown>, remainingPath),
        )
        .filter((v) => v !== undefined);
      const flat = results.flatMap((r) => (Array.isArray(r) ? r : [r]));
      return flat.length > 0 ? flat : undefined;
    }

    if (typeof current !== 'object') return undefined;
    current = (current as Record<string, unknown>)[keys[index]];
  }
  return current;
}

/**
 * Resolve the value for a single field rule against a segment node and context map.
 * @param rule - The field extraction rule describing source, transforms, and defaults.
 * @param node - The resolved segment node to read the source field from.
 * @param context - Key/value context injected by the caller (e.g. site, erpSource).
 * @returns The resolved and transformed value, falling back to `defaultValue` when applicable.
 */
function resolveField(
  rule: FieldRule,
  node: Record<string, unknown>,
  context: Record<string, unknown>,
): unknown {
  let value: unknown;

  if (rule.value !== undefined) {
    value = rule.value;
  } else if (rule.fromContext) {
    value = context[rule.fromContext];
  } else if (rule.source) {
    value = node[rule.source];
  }

  if (rule.transforms) {
    for (const id of rule.transforms) {
      value = TRANSFORMS[id](value);
    }
  }

  return value ?? rule.defaultValue;
}

/**
 * Pick one element from an array according to the segment rule's array strategy.
 * @param items - The array of items to pick from.
 * @param rule - The segment rule that defines the pick strategy (`first` or `firstWithProp`).
 * @returns The selected element, or `undefined` when the array is empty.
 */
function pickFromArray(items: Array<unknown>, rule: SegmentRule): unknown {
  if (items.length === 0) return undefined;

  if (rule.array === 'firstWithProp' && rule.arrayProp) {
    return (
      items.find(
        (item) =>
          typeof item === 'object' &&
          item !== null &&
          Boolean((item as Record<string, unknown>)[rule.arrayProp ?? '']),
      ) ?? items[0]
    );
  }
  return items[0];
}

/**
 * Apply a list of field rules to a segment node and return the resolved key/value pairs.
 * @param rules - The field extraction rules to apply.
 * @param node - The segment node to read source fields from.
 * @param context - Key/value context injected by the caller.
 * @returns A new record containing the resolved field values.
 */
function applyFields(
  rules: Array<FieldRule>,
  node: Record<string, unknown>,
  context: Record<string, unknown>,
): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const rule of rules) {
    const value = resolveField(rule, node, context);
    if (value !== undefined) {
      if (rule.targetGroup) {
        const group = (result[rule.targetGroup] ?? {}) as Record<
          string,
          unknown
        >;
        result[rule.targetGroup] = { ...group, [rule.target]: value };
      } else {
        result[rule.target] = value;
      }
    }
  }
  return result;
}

/**
 * Unwrap the IDOC node from a raw payload that may be direct (`{ IDOC: … }`) or wrapped (`{ <ROOT>: { IDOC: … } }`).
 * @param raw - The raw top-level JSON object received from EventHub.
 * @returns The inner IDOC node as a plain object, or `undefined` if it cannot be located.
 */
function unwrapIdoc(
  raw: Record<string, unknown>,
): Record<string, unknown> | undefined {
  if (raw['IDOC'] && typeof raw['IDOC'] === 'object') {
    return raw['IDOC'] as Record<string, unknown>;
  }
  for (const key of Object.keys(raw)) {
    if (!key.startsWith('@')) {
      const inner = raw[key];
      if (typeof inner === 'object' && inner !== null) {
        const idoc = (inner as Record<string, unknown>)['IDOC'];
        if (typeof idoc === 'object' && idoc !== null) {
          return idoc as Record<string, unknown>;
        }
      }
    }
  }
  return undefined;
}

/**
 * Resolve a `first` / `firstWithProp` array segment and return the extracted fields.
 * @param segRule - The segment rule with array pick strategy.
 * @param resolved - The raw value resolved from the IDOC node at the segment path.
 * @param context - Key/value context injected by the caller.
 * @returns A record of resolved field values for the picked element.
 */
function processPickedArraySegment(
  segRule: SegmentRule,
  resolved: unknown,
  context: Record<string, unknown>,
): Record<string, unknown> {
  let picked = pickFromArray(normalizeToArray(resolved), segRule);

  if (
    segRule.arrayItemSubPath &&
    typeof picked === 'object' &&
    picked !== null
  ) {
    picked = (picked as Record<string, unknown>)[segRule.arrayItemSubPath];
  }

  if (typeof picked === 'object' && picked !== null) {
    return applyFields(
      segRule.fields,
      picked as Record<string, unknown>,
      context,
    );
  }
  if (picked !== undefined && segRule.fields.length === 1) {
    return { [segRule.fields[0].target]: picked };
  }
  return {};
}

/**
 * Resolve a non-array segment and return the extracted fields.
 * @param segRule - The segment rule describing which fields to extract.
 * @param resolved - The raw value resolved from the IDOC node at the segment path.
 * @param context - Key/value context injected by the caller.
 * @returns A record of resolved field values, or an empty object if the segment is not a plain object.
 */
function processSingleObjectSegment(
  segRule: SegmentRule,
  resolved: unknown,
  context: Record<string, unknown>,
): Record<string, unknown> {
  if (
    typeof resolved !== 'object' ||
    resolved === null ||
    Array.isArray(resolved)
  )
    return {};
  return applyFields(
    segRule.fields,
    resolved as Record<string, unknown>,
    context,
  );
}

/**
 * Expand a set of in-progress records by cross-joining them with all nodes of a repeating segment.
 * @param records - The current list of partially built output records.
 * @param rule - The repeating segment rule (`array: 'all'`) whose fields to apply.
 * @param nodes - The array of segment nodes to iterate over.
 * @param context - Key/value context injected by the caller.
 * @returns A new array of records — one entry per original record × repeating node.
 */
function expandRepeatSegment(
  records: Array<Record<string, unknown>>,
  rule: SegmentRule,
  nodes: Array<Record<string, unknown>>,
  context: Record<string, unknown>,
): Array<Record<string, unknown>> {
  const expanded: Array<Record<string, unknown>> = [];
  for (const base of records) {
    for (const node of nodes) {
      expanded.push({ ...base, ...applyFields(rule.fields, node, context) });
    }
  }
  return expanded;
}

/**
 * Extract fields from a raw IDoc payload using a declarative mapping config.
 *
 * - Configs with NO `array: 'all'` segment → returns a single-element array.
 * - Configs WITH `array: 'all'` segment → returns N records (one per repeating element).
 * @param rawPayload  Raw IDoc JSON as received from EventHub
 * @param config      Declarative mapping configuration
 * @param context     Optional context values (e.g. site, erpSource)
 * @returns An array of typed output records extracted from the IDoc payload.
 */
export function extractIdocFields<T = Record<string, unknown>>(
  rawPayload: Record<string, unknown>,
  config: IdocMappingConfig,
  context: Record<string, unknown> = {},
): Array<T> {
  const idoc = unwrapIdoc(rawPayload);
  if (!idoc) return [];

  const baseRecord: Record<string, unknown> = {};
  const repeatSegments: Array<{
    rule: SegmentRule;
    nodes: Array<Record<string, unknown>>;
  }> = [];

  for (const segRule of config.segments) {
    const resolved = resolvePath(idoc, segRule.path);

    if (segRule.array === 'all') {
      const items = normalizeToArray(resolved) as Array<
        Record<string, unknown>
      >;
      if (items.length > 0) {
        repeatSegments.push({ rule: segRule, nodes: items });
      }
    } else if (segRule.array === 'first' || segRule.array === 'firstWithProp') {
      Object.assign(
        baseRecord,
        processPickedArraySegment(segRule, resolved, context),
      );
    } else {
      Object.assign(
        baseRecord,
        processSingleObjectSegment(segRule, resolved, context),
      );
    }
  }

  if (repeatSegments.length === 0) {
    return [baseRecord as T];
  }

  let records: Array<Record<string, unknown>> = [{ ...baseRecord }];
  for (const { rule, nodes } of repeatSegments) {
    records = expandRepeatSegment(records, rule, nodes, context);
  }

  const { excludeWhen } = config;
  if (excludeWhen && excludeWhen.length > 0) {
    records = records.filter(
      (record) =>
        !excludeWhen.some((rule) => record[rule.field] === rule.value),
    );
  }

  return records as Array<T>;
}

/**
 * Normalise the raw EventHub message body into a plain object.
 *
 * The Azure EventHub SDK delivers the body either as a pre-parsed object
 * (when the content-type is application/json) or as a raw JSON string.
 * Both forms are handled here so callers never need to branch on the type.
 * @param rawBody - The `body` field from the EventHub event (string or object).
 * @returns Parsed IDoc object, or `undefined` when the body is malformed or unsupported.
 */
export function parseEventHubBody(
  rawBody: unknown,
): Record<string, unknown> | undefined {
  if (
    typeof rawBody === 'object' &&
    rawBody !== null &&
    !Array.isArray(rawBody)
  ) {
    return rawBody as Record<string, unknown>;
  }

  if (typeof rawBody === 'string') {
    let parsed: unknown;
    try {
      parsed = JSON.parse(rawBody);
    } catch {
      return undefined;
    }
    if (
      typeof parsed !== 'object' ||
      parsed === null ||
      Array.isArray(parsed)
    ) {
      return undefined;
    }
    return parsed as Record<string, unknown>;
  }

  return undefined;
}

/**
 * Parses a SAP date string in YYYYMMDD format to a JavaScript Date object.
 * @param raw - The SAP date string to parse
 * @returns A Date object parsed from the input string, or undefined if input is invalid
 */
export function parseSapDate(raw: string): Date | undefined {
  if (!raw?.length || raw.length !== 8 || raw === '00000000') {
    return undefined;
  }
  const year = Number.parseInt(raw.slice(0, 4), 10);
  const month = Number.parseInt(raw.slice(4, 6), 10) - 1;
  const day = Number.parseInt(raw.slice(6, 8), 10);

  if ([year, month, day].some((part) => Number.isNaN(part))) {
    return undefined;
  }

  return new Date(year, month, day);
}

import { PROCESSING_STATUS, telemetryMetrics } from '@mesx/common-lib';

/**
 * Tracks telemetry metrics for an async function execution.
 * @param topic - The topic name for the event
 * @param entityId - The entity identifier
 * @param functionToExecute - The async function to execute and track
 */
export async function trackWithTelemetry(
  topic: string,
  entityId: string,
  functionToExecute: () => Promise<unknown>,
): Promise<void> {
  const startTime = Date.now();
  try {
    await functionToExecute();
    const duration = Date.now() - startTime;
    telemetryMetrics.trackEventProcessingDuration(
      duration,
      PROCESSING_STATUS.PROCESSED,
      entityId,
      topic,
    );
    telemetryMetrics.trackEventProcessed(
      PROCESSING_STATUS.PROCESSED,
      entityId,
      topic,
    );
  } catch (error) {
    const duration = Date.now() - startTime;
    telemetryMetrics.trackEventProcessingDuration(
      duration,
      PROCESSING_STATUS.INVALID,
      entityId,
      topic,
    );
    telemetryMetrics.trackEventProcessed(
      PROCESSING_STATUS.INVALID,
      entityId,
      topic,
    );
    throw error;
  }
}

/**
 * Tracks SQL telemetry metrics for an async database operation.
 * @param topic - The topic name for the event
 * @param entityId - The entity identifier
 * @param functionToExecute - The async database function to execute and track
 */
export async function trackSqlOperation(
  topic: string,
  entityId: string,
  functionToExecute: () => Promise<void>,
): Promise<void> {
  const startTime = Date.now();
  await functionToExecute();
  const duration = Date.now() - startTime;
  telemetryMetrics.trackEventProcessingDuration(
    duration,
    PROCESSING_STATUS.SQL,
    entityId,
    topic,
  );
  telemetryMetrics.trackEventProcessed(PROCESSING_STATUS.SQL, entityId, topic);
}

