import { Subscription } from '@azure/event-hubs';
import { Injectable, OnModuleInit, OnModuleDestroy } from '@nestjs/common';
import {
  PartitionInfo,
  performFinalCheckpoints,
} from '../common/helpers/eventhub-functions/checkpoint';
import {
  EventHubClients,
  initializeEventHub,
  cleanupEventHub,
} from '../common/helpers/eventhub-functions/initialization';
import { MessageProcessor } from '../common/helpers/eventhub-functions/message-processing';
import {
  createShutdownState,
  ShutdownState,
} from '../common/helpers/eventhub-functions/shutdown';
import {
  subscribeToEventHub,
  unsubscribeFromEventHub,
} from '../common/helpers/eventhub-functions/subscription';
import { IntegrationConfigService } from '@/idoc/config/eventhub-sdk/integration-config.service';
import { IDOC_FAMILY } from '@/idoc/idoc-events/message-handler.interface';
import { MessageProcessingService } from '@/idoc/idoc-events/message-processing.service';
import { AppLogger } from '@/shared/logger/app-logger';

@Injectable()
export class EventHubIdocLoirnhService
  implements OnModuleInit, OnModuleDestroy
{
  private clients: EventHubClients | null = null;

  private subscription: Subscription | null = null;

  private partitionInfo: Map<string, PartitionInfo> | null = null;

  private readonly shutdownState: ShutdownState = createShutdownState();

  public constructor(
    private readonly configService: IntegrationConfigService,
    private readonly messageProcessingService: MessageProcessingService,
    private readonly logger: AppLogger,
  ) {}

  public async onModuleInit(): Promise<void> {
    await this.initialize();
  }

  public async onModuleDestroy(): Promise<void> {
    await this.cleanup();
  }

  private async initialize(): Promise<void> {
    const context = {
      method: 'initialize',
      service: EventHubIdocLoirnhService.name,
    };

    try {
      this.logger.log('Initializing LOIRNH idoc EventHub service', context);

      const eventHubConfig = this.configService.getLoirnhConfig();

      this.clients = await initializeEventHub(eventHubConfig, this.logger);

      const processor: MessageProcessor = {
        processMessage: async (message: unknown): Promise<void> => {
          await this.messageProcessingService.processIdoc(
            message,
            IDOC_FAMILY.loirnh,
          );
        },
      };

      const errorRecoveryConfig = {
        enabled: true,
        eventHubConfig,
      };

      const subscriptionResult = subscribeToEventHub(processor, {
        checkpointConfig: {
          ...eventHubConfig,
          checkpointInterval: this.configService.loirnhCheckpointInterval,
        },
        clients: this.clients,
        errorRecoveryConfig,
        logger: this.logger,
        processingConfig: {
          serviceName: EventHubIdocLoirnhService.name,
          topicName: 'loirnh',
        },
        shutdownState: this.shutdownState,
        subscriptionConfig: {
          maxBatchSize: 1,
          enableCheckpointing: true,
        },
      });

      this.subscription = subscriptionResult.subscription;
      this.partitionInfo = subscriptionResult.partitionInfo;

      this.logger.log(
        'LOIRNH idoc EventHub service initialized successfully',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Failed to initialize LOIRNH idoc EventHub service: ${(error as Error).message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      throw error;
    }
  }

  private async cleanup(): Promise<void> {
    const context = {
      method: 'cleanup',
      service: EventHubIdocLoirnhService.name,
    };

    try {
      this.logger.log('Cleaning up LOIRNH idoc EventHub service', context);

      this.shutdownState.value = true;

      if (this.clients && this.partitionInfo) {
        await performFinalCheckpoints(
          this.clients.checkpointStore,
          {
            consumerGroup: this.configService.loirnhConsumerGroup,
            eventHubName: this.configService.loirnhEventHubName,
            eventHubNamespace: this.configService.loirnhEventHubNamespace,
            checkpointInterval: this.configService.loirnhCheckpointInterval,
          },
          this.partitionInfo,
          this.logger,
        );
      }

      if (this.subscription) {
        await unsubscribeFromEventHub(
          this.subscription,
          EventHubIdocLoirnhService.name,
          this.logger,
        );
        this.subscription = null;
      }

      if (this.clients) {
        await cleanupEventHub(this.clients, this.logger);
        this.clients = null;
      }

      this.partitionInfo = null;

      this.logger.log(
        'LOIRNH idoc EventHub service cleanup completed',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Error during LOIRNH idoc EventHub service cleanup: ${(error as Error).message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }
}

