@Injectable()
export class EventHubIdocMdmEquipmentSavereplicaService
  implements OnModuleInit, OnModuleDestroy
{
  private clients: EventHubClients | null = null;

  private subscription: Subscription | null = null;

  private partitionInfo: Map<string, PartitionInfo> | null = null;

  private readonly shutdownState: ShutdownState = createShutdownState();

  public constructor(
    private readonly configService: IntegrationConfigService,
    private readonly messageProcessingService: MessageProcessingService,
    private readonly logger: AppLogger,
  ) {}

  public async onModuleInit(): Promise<void> {
    await this.initialize();
  }

  public async onModuleDestroy(): Promise<void> {
    await this.cleanup();
  }

  private async initialize(): Promise<void> {
    const context = {
      method: 'initialize',
      service: EventHubIdocMdmEquipmentSavereplicaService.name,
    };

    try {
      this.logger.log(
        'Initializing MDM_EQUIPMENT_SAVEREPLICA idoc EventHub service',
        context,
      );

      const eventHubConfig =
        this.configService.getMdmEquipmentSavereplicaConfig();

      this.clients = await initializeEventHub(eventHubConfig, this.logger);

      const processor: MessageProcessor = {
        processMessage: async (message: unknown): Promise<void> => {
          await this.messageProcessingService.processIdoc(
            message,
            IDOC_FAMILY.mdmEquipmentSavereplica,
          );
        },
      };

      const errorRecoveryConfig = {
        enabled: true,
        eventHubConfig,
      };

      const subscriptionResult = subscribeToEventHub(processor, {
        checkpointConfig: {
          ...eventHubConfig,
          checkpointInterval:
            this.configService.mdmEquipmentSavereplicaCheckpointInterval,
        },
        clients: this.clients,
        errorRecoveryConfig,
        logger: this.logger,
        processingConfig: {
          serviceName: EventHubIdocMdmEquipmentSavereplicaService.name,
          topicName: 'mdm-equipment-savereplica',
        },
        shutdownState: this.shutdownState,
        subscriptionConfig: {
          maxBatchSize: 1,
          enableCheckpointing: true,
        },
      });

      this.subscription = subscriptionResult.subscription;
      this.partitionInfo = subscriptionResult.partitionInfo;

      this.logger.log(
        'MDM_EQUIPMENT_SAVEREPLICA idoc EventHub service initialized successfully',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Failed to initialize MDM_EQUIPMENT_SAVEREPLICA idoc EventHub service: ${(error as Error).message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
      throw error;
    }
  }

  private async cleanup(): Promise<void> {
    const context = {
      method: 'cleanup',
      service: EventHubIdocMdmEquipmentSavereplicaService.name,
    };

    try {
      this.logger.log(
        'Cleaning up MDM_EQUIPMENT_SAVEREPLICA idoc EventHub service',
        context,
      );

      this.shutdownState.value = true;

      if (this.clients && this.partitionInfo) {
        await performFinalCheckpoints(
          this.clients.checkpointStore,
          {
            consumerGroup:
              this.configService.mdmEquipmentSavereplicaConsumerGroup,
            eventHubName:
              this.configService.mdmEquipmentSavereplicaEventHubName,
            eventHubNamespace:
              this.configService.mdmEquipmentSavereplicaEventHubNamespace,
            checkpointInterval:
              this.configService.mdmEquipmentSavereplicaCheckpointInterval,
          },
          this.partitionInfo,
          this.logger,
        );
      }

      if (this.subscription) {
        await unsubscribeFromEventHub(
          this.subscription,
          EventHubIdocMdmEquipmentSavereplicaService.name,
          this.logger,
        );
        this.subscription = null;
      }

      if (this.clients) {
        await cleanupEventHub(this.clients, this.logger);
        this.clients = null;
      }

      this.partitionInfo = null;

      this.logger.log(
        'MDM_EQUIPMENT_SAVEREPLICA idoc EventHub service cleanup completed',
        context,
      );
    } catch (error) {
      this.logger.error(
        `Error during MDM_EQUIPMENT_SAVEREPLICA idoc EventHub service cleanup: ${(error as Error).message}`,
        context,
        error instanceof Error ? error : new Error(String(error)),
      );
    }
  }
}

