import { JobsLogContext } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { DiscoveryService } from '@nestjs/core';
import {
  idocHandler,
  IIdocHandler,
  IIdocHandlerRegistry,
} from '@/idoc/idoc-events/message-handler.interface';
import { AppLogger } from '@/shared/logger/app-logger';

@Injectable()
export class HandlerRegistry implements IIdocHandlerRegistry, OnModuleInit {
  private readonly handlers: Map<string, IIdocHandler> = new Map();

  private readonly familyHandlers: Map<string, Array<IIdocHandler>> = new Map();

  private readonly context: JobsLogContext = {
    method: 'HandlerRegistry',
    service: 'HandlerRegistry',
  };

  public constructor(
    private readonly discoveryService: DiscoveryService,
    private readonly customLogger: AppLogger,
  ) {}

  public onModuleInit(): void {
    const providers = this.discoveryService.getProviders();
    for (const wrapper of providers) {
      const metadata = this.discoveryService.getMetadataByDecorator(
        idocHandler,
        wrapper,
      );
      if (metadata !== undefined && wrapper.instance) {
        const handler = wrapper.instance as IIdocHandler;
        const meta = handler.getMetadata();
        this.register(`${meta.idocFamily}::${meta.version}`, handler);
      }
    }
  }

  public register(key: string, handler: IIdocHandler): void {
    this.handlers.set(key, handler);

    const family = handler.getMetadata().idocFamily;
    let group = this.familyHandlers.get(family);
    if (!group) {
      group = [];
      this.familyHandlers.set(family, group);
    }
    group.push(handler);

    this.customLogger.debug(`Registered IDoc handler: ${key}`, this.context);
  }

  public findHandler(
    rawPayload: Record<string, unknown>,
    expectedFamily?: string,
  ): IIdocHandler | undefined {
    const candidates = expectedFamily
      ? this.familyHandlers.get(expectedFamily) ?? []
      : [...this.familyHandlers.values()].flat();

    for (const handler of candidates) {
      if (handler.canHandle(rawPayload)) {
        const meta = handler.getMetadata();
        this.customLogger.debug(
          `Matched handler ${meta.idocFamily}::${meta.version}`,
          this.context,
        );
        return handler;
      }
    }

    this.customLogger.warn(
      `No handler found for IDoc${
        expectedFamily ? ` (family=${expectedFamily})` : ''
      } with keys: ${Object.keys(rawPayload).join(', ')}`,
      this.context,
    );
    return undefined;
  }
}

