import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { PropertySemanticsValidatorService } from '@/idoc/modules/common/property-semantics/property-semantics-validator.service';
import { EquipmentClassProperty } from '@/idoc/modules/loiwcs/entities/equipment-class-property.entity';

@Module({
  imports: [TypeOrmModule.forFeature([EquipmentClassProperty])],
  providers: [PropertySemanticsValidatorService],
  exports: [PropertySemanticsValidatorService],
})
export class PropertySemanticsValidatorModule {}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { EquipmentClassProperty } from '@/idoc/modules/loiwcs/entities/equipment-class-property.entity';

export interface PropertyValidationInput {
  /** The `code` field from the incoming mapping. */
  code: string;
  /** The `equipment_class_id` this property belongs to. */
  equipmentClassId: number;
  /** The value being assigned — may be a scalar or array. */
  value: unknown;
}

export interface PropertyValidationResult {
  valid: boolean;
  errors: Array<string>;
}

/** Known data-type codes stored in `property_data_type.code`. */
const enum DATA_TYPE_CODE {
  STRING = 'STRING',
  INTEGER = 'INTEGER',
  DECIMAL = 'DECIMAL',
  BOOLEAN = 'BOOLEAN',
  DATE = 'DATE',
}

/**
 * Safely stringify a value for error messages.
 * Objects are JSON-stringified; primitives use String().
 * @param value - The value to stringify.
 * @returns A string representation of the value.
 */
function stringifyValue(value: unknown): string {
  if (value === null || value === undefined) {
    return String(value);
  }
  if (typeof value === 'object') {
    return JSON.stringify(value);
  }
  return String(value as string | number | boolean | bigint | symbol);
}

@Injectable()
export class PropertySemanticsValidatorService {
  private static validateCardinality(
    ecp: EquipmentClassProperty,
    value: unknown,
    errors: Array<string>,
  ): void {
    const cardinality = ecp.propertySemanticsJson?.cardinality;
    if (!cardinality) return;

    const isArray = Array.isArray(value);
    if (cardinality === 'single' && isArray) {
      errors.push(
        `Invalid cardinality: expected single value for property "${ecp.code}"`,
      );
    } else if (cardinality === 'array' && !isArray) {
      errors.push(
        `Invalid cardinality: expected array value for property "${ecp.code}"`,
      );
    }
  }

  private static validateClassPropertyType(
    ecp: EquipmentClassProperty,
    value: unknown,
    errors: Array<string>,
  ): void {
    const semantics = ecp.propertySemanticsJson;
    if (!semantics?.class_property_type) return;

    const {
      class_property_type: classPropertyType,
      default_value: defaultValue,
    } = semantics;

    switch (classPropertyType) {
      case 'ClassType': {
        if (value !== undefined && value !== null && value !== defaultValue) {
          errors.push(
            `ClassType property "${ecp.code}" cannot be overridden at instance level. Expected: ${stringifyValue(defaultValue)}`,
          );
        }
        if (value === undefined || value === null) {
          errors.push(
            `ClassType property "${ecp.code}" value must match default_value "${stringifyValue(defaultValue)}"`,
          );
        }
        break;
      }

      case 'InstanceType': {
        if (value === undefined || value === null) {
          errors.push(
            `InstanceType property "${ecp.code}" must be provided at instance level`,
          );
        }
        break;
      }

      case 'DefaultType': {
        break;
      }

      default: {
        errors.push(
          `Unknown class_property_type "${classPropertyType}" for property "${ecp.code}"`,
        );
      }
    }
  }

  private static validateAllowedValues(
    ecp: EquipmentClassProperty,
    value: unknown,
    errors: Array<string>,
  ): void {
    const allowed =
      (ecp.propertySemanticsJson?.allowed_values as Array<unknown>) || [];
    if (allowed.length === 0) return;

    const valuesToCheck: Array<unknown> = Array.isArray(value)
      ? value
      : [value];

    for (const v of valuesToCheck) {
      if (!allowed.includes(v)) {
        errors.push(
          `Value not allowed for property "${ecp.code}". Received: "${stringifyValue(v)}". Allowed values: [${allowed.join(', ')}]`,
        );
      }
    }
  }

  private static validateCode(
    ecpCode: string,
    inputCode: string,
    errors: Array<string>,
  ): void {
    if (ecpCode !== inputCode) {
      errors.push(
        `Code mismatch: mapping.code "${inputCode}" does not match equipment_class_property.code "${ecpCode}"`,
      );
    }
  }

  /**
   * Returns a short description of the mismatch, or `null` if the value is
   * compatible with the expected type code.
   * @param typeCode - The expected data type code (e.g., STRING, INTEGER).
   * @param value - The value to check against the expected type.
   * @returns A string describing the mismatch, or null if the type matches.
   */
  private static checkDataTypeMismatch(
    typeCode: string,
    value: unknown,
  ): string | null {
    switch (typeCode) {
      case DATA_TYPE_CODE.STRING: {
        return typeof value === 'string' ? null : 'expected string';
      }

      case DATA_TYPE_CODE.INTEGER: {
        if (typeof value === 'number' && Number.isInteger(value)) return null;
        if (typeof value === 'string' && /^-?\d+$/.test(value)) return null;
        return 'expected integer';
      }

      case DATA_TYPE_CODE.DECIMAL: {
        if (typeof value === 'number' && Number.isFinite(value)) return null;
        if (typeof value === 'string' && !Number.isNaN(Number(value))) {
          return null;
        }
        return 'expected decimal';
      }

      case DATA_TYPE_CODE.BOOLEAN: {
        if (typeof value === 'boolean') return null;
        if (value === 'true' || value === 'false') return null;
        return 'expected boolean';
      }

      case DATA_TYPE_CODE.DATE: {
        if (value instanceof Date) return null;
        if (typeof value === 'string' && !Number.isNaN(Date.parse(value))) {
          return null;
        }
        return 'expected date';
      }

      default: {
        return null;
      }
    }
  }

  private static validateDataType(
    ecp: EquipmentClassProperty,
    value: unknown,
    errors: Array<string>,
  ): void {
    const typeCode = ecp.propertyDataType?.code?.toUpperCase();
    if (!typeCode) return;

    const valuesToCheck: Array<unknown> = Array.isArray(value)
      ? value
      : [value];

    for (const v of valuesToCheck) {
      if (v === undefined || v === null) {
        return;
      }

      const typeMismatch =
        PropertySemanticsValidatorService.checkDataTypeMismatch(typeCode, v);
      if (typeMismatch) {
        errors.push(
          `Invalid data type for property "${ecp.code}": expected ${typeCode}, got "${stringifyValue(v)}" (${typeMismatch})`,
        );
      }
    }
  }

  private static validateStringLength(
    ecp: EquipmentClassProperty,
    value: string,
    errors: Array<string>,
  ): void {
    if (ecp.length !== null && value.length > ecp.length) {
      errors.push(
        `Length exceeded for property "${ecp.code}": max length = ${ecp.length}, got ${value.length}`,
      );
    }
  }

  private static validateDecimalPrecisionScale(
    ecp: EquipmentClassProperty,
    value: unknown,
    errors: Array<string>,
  ): void {
    const numberString = String(value);
    const decimalIndex = numberString.indexOf('.');
    if (decimalIndex === -1) return;

    const integerDigits = decimalIndex;
    const fractionalDigits = numberString.length - decimalIndex - 1;

    if (ecp.scale !== null && fractionalDigits > ecp.scale) {
      errors.push(
        `Scale exceeded for property "${ecp.code}": max scale = ${ecp.scale}, got ${fractionalDigits} decimal places`,
      );
    }

    if (ecp.length !== null) {
      const totalDigits = integerDigits + fractionalDigits;
      if (totalDigits > ecp.length) {
        errors.push(
          `Precision exceeded for property "${ecp.code}": max precision = ${ecp.length}, got ${totalDigits} total digits`,
        );
      }
    }
  }

  private static validateLengthScale(
    ecp: EquipmentClassProperty,
    value: unknown,
    errors: Array<string>,
  ): void {
    const typeCode = ecp.propertyDataType?.code?.toUpperCase();
    const valuesToCheck: Array<unknown> = Array.isArray(value)
      ? value
      : [value];

    for (const v of valuesToCheck) {
      if (v === undefined || v === null) return;

      if (typeCode === DATA_TYPE_CODE.STRING && typeof v === 'string') {
        PropertySemanticsValidatorService.validateStringLength(ecp, v, errors);
        return;
      }

      if (typeCode === DATA_TYPE_CODE.DECIMAL) {
        PropertySemanticsValidatorService.validateDecimalPrecisionScale(
          ecp,
          v,
          errors,
        );
      }
    }
  }

  public constructor(
    @InjectRepository(EquipmentClassProperty)
    private readonly ecpRepository: Repository<EquipmentClassProperty>,
  ) {}

  /**
   * Validate a single property value against the metadata stored in
   * `equipment_class_property`.
   *
   * Returns a result object so that callers can decide whether to abort
   * or collect multiple errors.
   * @param input - The property validation input containing code, equipmentClassId, and value.
   * @returns An object indicating whether the property is valid and any associated error messages.
   */
  public async validate(
    input: PropertyValidationInput,
  ): Promise<PropertyValidationResult> {
    const errors: Array<string> = [];

    const ecp = await this.ecpRepository.findOne({
      where: {
        code: input.code,
        equipmentClassId: input.equipmentClassId,
      },
      relations: ['propertyDataType'],
    });

    if (!ecp) {
      return {
        valid: false,
        errors: [
          `Property "${input.code}" does not exist for equipment class id ${input.equipmentClassId}`,
        ],
      };
    }

    PropertySemanticsValidatorService.validateCode(
      ecp.code,
      input.code,
      errors,
    );
    PropertySemanticsValidatorService.validateCardinality(
      ecp,
      input.value,
      errors,
    );
    PropertySemanticsValidatorService.validateClassPropertyType(
      ecp,
      input.value,
      errors,
    );
    PropertySemanticsValidatorService.validateAllowedValues(
      ecp,
      input.value,
      errors,
    );
    PropertySemanticsValidatorService.validateDataType(
      ecp,
      input.value,
      errors,
    );
    PropertySemanticsValidatorService.validateLengthScale(
      ecp,
      input.value,
      errors,
    );

    return { valid: errors.length === 0, errors };
  }
}

