/**
 * Typed output produced by the LOIRNH mapping engine for a LOIRNH01 IDoc.
 * One record per E1CRHSL segment (the segment may appear multiple times).
 * Field names use MES business terms; SAP segment origins are noted in comments.
 *
 * Segment mapping:
 *  E1CRHSL.OBJID_HO → childObjectId  (child  equipment, joined on equipment.sap_obj_id)
 *  E1CRHSL.OBJID_UP → parentObjectId (parent equipment, joined on equipment.sap_obj_id)
 */
export class IdocLoirnhDto {
  /** E1CRHSL.OBJID_HO — SAP object id of the child equipment */
  public childObjectId?: string;

  /** E1CRHSL.OBJID_UP — SAP object id of the parent equipment */
  public parentObjectId?: string;
