import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import {
  LOIRNH_V1_DIRECT_CONFIG,
  LOIRNH_V1_WRAPPED_CONFIG,
} from '@/idoc/common/config/idoc-mapping-configs';
import { IdocHandlerHelpers } from '@/idoc/common/helpers/idoc-handler.helpers';
import {
  extractIdocFields,
  IdocMappingConfig,
} from '@/idoc/common/helpers/idoc-mapper-engine';
import {
  idocHandler,
  IIdocHandler,
  IdocHandlerMetadata,
  IDOC_FAMILY,
} from '@/idoc/idoc-events/message-handler.interface';
import { IdocLoirnhDto } from '@/idoc/modules/loirnh/dto/idoc-loirnh.dto';
import { LoirnhHierarchyService } from '@/idoc/modules/loirnh/service/loirnh-hierarchy.service';
import { AppLogger } from '@/shared/logger/app-logger';

/**
 * LOIRNH handler — equipment hierarchy relations.
 *
 * Supports both LOIRNH layout variants via config `matches` predicates:
 *   - direct:  E1CRHSL segments appear directly under the IDOC node.
 *   - wrapped: E1CRHHL[] wrappers each contain E1CRHSL[] children.
 *
 * The SAP root node filter (parentObjectId = '00000000') and the config selection
 * are fully expressed in the mapping configs, with no imperative fallback.
 */
@idocHandler(IDOC_FAMILY.loirnh)
@Injectable()
export class LoirnhHandler implements IIdocHandler {
  /** Ordered list of LOIRNH configs; the first one whose `matches` returns true is used. */
  private static readonly configs: Array<IdocMappingConfig> = [
    LOIRNH_V1_DIRECT_CONFIG,
    LOIRNH_V1_WRAPPED_CONFIG,
  ];

  /**
   * Select the appropriate LOIRNH config by evaluating each config's `matches`
   * predicate against the unwrapped IDOC node.
   * @param rawPayload - The raw IDoc payload.
   * @returns The first matching config, or `undefined` if none matches.
   */
  private static selectConfig(
    rawPayload: Record<string, unknown>,
  ): IdocMappingConfig | undefined {
    const idoc = IdocHandlerHelpers.getIdocNode(rawPayload);
    return LoirnhHandler.configs.find((c) => !c.matches || c.matches(idoc));
  }

  /**
   * Validate a LOIRNH record has both child and parent object IDs.
   * @param record - The DTO to validate.
   * @returns `true` if both `childObjectId` and `parentObjectId` are present.
   */
  private static validate(record: IdocLoirnhDto): boolean {
    return !!record.childObjectId && !!record.parentObjectId;
  }

  private readonly familyPattern = /loirnh/i;

  private readonly metadata: IdocHandlerMetadata = {
    description: 'LOIRNH hierarchy relations',
    idocFamily: IDOC_FAMILY.loirnh,
    version: 'generic',
  };

  public constructor(
    private readonly customLogger: AppLogger,
    private readonly loirnhHierarchyService: LoirnhHierarchyService,
  ) {}

  public canHandle(rawPayload: Record<string, unknown>): boolean {
    const context: JobsLogContext = {
      method: 'canHandle',
      service: 'LoirnhHandler',
    };
    const idoc = IdocHandlerHelpers.getIdocNode(rawPayload);
    const ediDc40 = IdocHandlerHelpers.getNode(idoc['EDI_DC40']);
    const mestyp = ediDc40?.['MESTYP'];
    const result =
      typeof mestyp === 'string' && this.familyPattern.test(mestyp);
    this.customLogger.debug(
      `CanHandle result: ${result} (MESTYP=${mestyp})`,
      context,
    );
    return result;
  }

  private extract(rawPayload: Record<string, unknown>): Array<IdocLoirnhDto> {
    const context: JobsLogContext = {
      method: 'extract',
      service: 'LoirnhHandler',
    };
    this.customLogger.debug('Starting LOIRNH extraction', context);

    const config = LoirnhHandler.selectConfig(rawPayload);
    if (!config) {
      this.customLogger.warn(
        'No matching LOIRNH config found for payload',
        context,
      );
      return [];
    }

    this.customLogger.debug(`Selected config: ${config.id}`, context);

    const records = extractIdocFields<IdocLoirnhDto>(rawPayload, config);

    this.customLogger.debug(
      `Extracted ${records.length} records (root nodes excluded by config)`,
      context,
    );

    return records;
  }

  public getMetadata(): IdocHandlerMetadata {
    return this.metadata;
  }

  private async persist(records: Array<IdocLoirnhDto>): Promise<void> {
    const context: JobsLogContext = {
      method: 'persist',
      service: 'LoirnhHandler',
    };
    await Promise.all(
      records.map(async (record) => {
        if (!LoirnhHandler.validate(record)) {
          this.customLogger.warn(
            `Invalid LOIRNH record, skipping: ${JSON.stringify(record)}`,
            context,
          );
          return;
        }
        await this.loirnhHierarchyService.linkHierarchy(record);
      }),
    );
  }

  public async handle(rawPayload: Record<string, unknown>): Promise<void> {
    await this.persist(this.extract(rawPayload));
  }
}

export interface HierarchyPayload {
  childObjectId: string;
  parentObjectId: string;
}

import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { Equipment } from '@/idoc/modules/common/entities/equipment.entity';
import { LoirnhHandler } from '@/idoc/modules/loirnh/handler/loirnh.handler';
import { LoirnhHierarchyService } from '@/idoc/modules/loirnh/service/loirnh-hierarchy.service';

@Module({
  imports: [TypeOrmModule.forFeature([Equipment])],
  providers: [LoirnhHierarchyService, LoirnhHandler],
})
export class LoirnhModule {}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, IsNull, Repository } from 'typeorm';
import { trackSqlOperation } from '@/idoc/common/helpers/telemetry.helper';
import { Equipment } from '@/idoc/modules/common/entities/equipment.entity';
import { IdocLoirnhDto } from '@/idoc/modules/loirnh/dto/idoc-loirnh.dto';
import { EquipmentLevel } from '@/idoc/modules/loiwcs/entities/equipment-level.entity';
import { AppLogger } from '@/shared/logger/app-logger';

@Injectable()
export class LoirnhHierarchyService {
  // Equipment level code for the plant-level (site) equipment row
  private static readonly plantLevelCode = 'site';

  // Equipment level codes whose null-parent rows should be backfilled to the plant.
  // Must match the codes stored by EquipmentLevelResolverService (VERWE → levelCode map):
  //   LINE → productionLine, UAP → area, 0007 → workCenter
  private static readonly rootLevelCodes = [
    'productionLine',
    'area',
    'workCenter',
  ];

  private readonly context: JobsLogContext = {
    method: '',
    service: LoirnhHierarchyService.name,
  };

  public constructor(
    @InjectRepository(Equipment)
    private readonly equipmentRepository: Repository<Equipment>,
    private readonly customLogger: AppLogger,
  ) {}

  /**
   * Link child → parent by resolving E1CRHSL segments against existing
   * `isa95.equipment` records.
   *
   * Column mapping:
   *  E1CRHSL.OBJID_HO → child  equipment (join on equipment.sap_obj_id)
   *  E1CRHSL.OBJID_UP → parent equipment (join on equipment.sap_obj_id)
   *
   * Both must already exist — LOIWCS must have been received first.
   * Logs a warning and returns without error if either side cannot be resolved.
   * @param payload - The LOIRNH DTO containing `OBJID_HO` (child) and `OBJID_UP` (parent) SAP object IDs.
   */
  public async linkHierarchy(payload: IdocLoirnhDto): Promise<void> {
    const context = { ...this.context, method: 'linkHierarchy' };
    if (!payload) {
      this.customLogger.error('LOIRNH payload is empty', context);
      return;
    }

    const { childObjectId, parentObjectId } = payload;

    if (!childObjectId || !parentObjectId) {
      this.customLogger.error(
        `LOIRNH01 rejected: missing childObjectId or parentObjectId (childObjectId=${childObjectId}, parentObjectId=${parentObjectId})`,
        context,
      );
      return;
    }

    const childSapObjectId = Number(childObjectId);
    const parentSapObjectId = Number(parentObjectId);

    if (Number.isNaN(childSapObjectId) || Number.isNaN(parentSapObjectId)) {
      this.customLogger.error(
        `LOIRNH01 rejected: invalid numeric identifiers (childObjectId=${childObjectId}, parentObjectId=${parentObjectId})`,
        context,
      );
      return;
    }

    // Resolve child and parent in parallel (primary lookup: by sap_obj_id)
    const [child, parent] = await Promise.all([
      this.equipmentRepository.findOne({
        where: { sapObjId: childSapObjectId },
        select: ['id', 'plant', 'sapObjId'],
      }),
      this.equipmentRepository.findOne({
        where: { sapObjId: parentSapObjectId },
        select: ['id', 'plant', 'sapObjId'],
      }),
    ]);

    if (!child) {
      this.customLogger.error(
        `LOIRNH01 rejected: child equipment with childObjectId=${childObjectId} does not exist. ` +
          `Integrate the corresponding LOIWCS IDoc before sending LOIRNH01.`,
        context,
      );
      return;
    }

    if (!parent) {
      this.customLogger.error(
        `LOIRNH01 rejected: parent equipment with parentObjectId=${parentObjectId} does not exist. ` +
          `Integrate the corresponding LOIWCS IDoc before sending LOIRNH01.`,
        context,
      );
      return;
    }

    await trackSqlOperation(
      'equipment-hierarchy',
      String(child.sapObjId),
      async () => {
        await this.equipmentRepository.update(
          { plant: child.plant, id: child.id },
          { parentEquipmentId: parent.id },
        );
      },
    );

    this.customLogger.debug(
      `Hierarchy linked: childObjectId=${childObjectId} (id=${child.id}) → parentObjectId=${parentObjectId} (id=${parent.id})`,
      context,
    );

    await this.linkRootEquipmentToPlant(child.plant, context);
  }

  /**
   * After a hierarchy link is established, backfill any equipment in the same
   * plant that has a root-level type (productionLine / area / workCenter) and
   * still has no parent. Those rows are linked to the plant-level equipment.
   * @param plant - The plant number to backfill root equipment for.
   * @param context - The logging context.
   */
  private async linkRootEquipmentToPlant(
    plant: number,
    context: JobsLogContext,
  ): Promise<void> {
    const levelRepo =
      this.equipmentRepository.manager.getRepository(EquipmentLevel);

    // ── 1. Resolve level IDs from equipment_level ─────────────────────────────
    const [rootLevels, siteLevel] = await Promise.all([
      levelRepo.find({
        where: { code: In(LoirnhHierarchyService.rootLevelCodes) },
        select: ['id', 'code'],
      }),
      levelRepo.findOne({
        where: { code: LoirnhHierarchyService.plantLevelCode },
        select: ['id'],
      }),
    ]);

    if (!siteLevel) {
      this.customLogger.warn(
        `linkRootEquipmentToPlant: no equipment_level row found for code='${LoirnhHierarchyService.plantLevelCode}' — skipping backfill`,
        context,
      );
      return;
    }

    if (rootLevels.length === 0) {
      this.customLogger.warn(
        `linkRootEquipmentToPlant: no equipment_level rows found for codes [${LoirnhHierarchyService.rootLevelCodes.join(', ')}] — skipping backfill`,
        context,
      );
      return;
    }

    // ── 2. Find the plant-level equipment row for this plant ─────────────────
    const plantEquipment = await this.equipmentRepository.findOne({
      where: { plant, equipmentLevelId: siteLevel.id },
      select: ['id'],
    });

    if (!plantEquipment) {
      this.customLogger.warn(
        `linkRootEquipmentToPlant: no equipment with level='${LoirnhHierarchyService.plantLevelCode}' found for plant=${plant} — skipping backfill`,
        context,
      );
      return;
    }

    // ── 3. Find all root equipment with no parent in this plant ──────────────
    //
    // SELECT id FROM isa95.equipment
    // WHERE  equipment_level_id IN (:rootLevelIds)
    //   AND  plant               = :plant
    //   AND  parent_equipment_id IS NULL
    const rootLevelIds = rootLevels.map((l) => l.id);

    const candidates = await this.equipmentRepository.find({
      where: {
        plant,
        equipmentLevelId: In(rootLevelIds),
        parentEquipmentId: IsNull(),
      },
      select: ['id'],
    });

    if (candidates.length === 0) {
      return;
    }

    const candidateIds = candidates.map((c) => c.id);

    // ── 4. Batch-update: set parentEquipmentId = plant equipment ─────────────
    await trackSqlOperation(
      'equipment-root-backfill',
      String(plant),
      async () => {
        await this.equipmentRepository.update(
          { id: In(candidateIds), parentEquipmentId: IsNull(), plant },
          { parentEquipmentId: plantEquipment.id },
        );
      },
    );
  }
}

/**
 * Typed output produced by the LOIWCS mapping engine for a LOIWCS02/03 IDoc.
 * Field names use MES business terms; SAP segment origins are noted in comments.
 *
 * Segment mapping:
 *  EDI_DC40.SNDPOR    → erpSource  (normalised by 'erpSource' transform)
 *  E1CRHDL.ARBPL      → code
 *  E1CRHDL.WERKS      → plant
 *  E1CRHDL.OBJID      → sapObjectId
 *  E1CRHDL.PARV6      → properties.costCenter
 *  E1CRHDL.VGWTS      → properties.stdValueKey
 *  E1CRTXL.KTEXT      → description
 *  ZMII_E1CRHDL.VERWE → equipmentLevel (mapped to DB id via VERWE_TO_LEVEL_ID)
 */
export class IdocLoiwcsDto {
  /** Derived from EDI_DC40.SNDPOR — 3-char ERP source identifier (e.g. "TC2") */
  public erpSource?: string;

  /** E1CRHDL.ARBPL — equipment code (work centre), trimmed */
  public code?: string;

  /** E1CRHDL.WERKS — plant number as string (converted to number by the service) */
  public plant?: string;

  /** E1CRHDL.OBJID — SAP object identifier */
  public sapObjectId?: string;

  /** Pre-mapped properties from E1CRHDL (costCenter, stdValueKey) */
  public properties?: Record<string, unknown>;

  /** E1CRTXL.KTEXT — equipment description */
  public description?: string;

  /** ZMII_E1CRHDL.VERWE — SAP usage indicator (UAP / LINE / 0007) */
  public equipmentLevel?: string;
}

