import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import {
  LOIWCS_V2_CONFIG,
  LOIWCS_V3_CONFIG,
} from '@/idoc/common/config/idoc-mapping-configs';
import { IdocHandlerHelpers } from '@/idoc/common/helpers/idoc-handler.helpers';
import {
  extractIdocFields,
  IdocMappingConfig,
} from '@/idoc/common/helpers/idoc-mapper-engine';
import {
  idocHandler,
  IIdocHandler,
  IdocHandlerMetadata,
  IDOC_FAMILY,
} from '@/idoc/idoc-events/message-handler.interface';
import { IdocLoiwcsDto } from '@/idoc/modules/loiwcs/dto/idoc-loiwcs.dto';
import { LoiwcsEquipmentService } from '@/idoc/modules/loiwcs/service/loiwcs-equipment.service';
import { AppLogger } from '@/shared/logger/app-logger';

/**
 * LOIWCS handler — equipment master data.
 *
 * Supports all LOIWCS structural variants automatically via config `matches` predicates:
 *   - v2: ZMII_E1CRHDL at IDOC root level (not nested in E1CRHDL).
 *   - v3: ZMII_E1CRHDL nested under E1CRHDL, or absent at root level.
 *
 * The config is selected by evaluating each candidate's `matches` predicate against
 * the unwrapped IDOC node, eliminating imperative variant detection.
 */
@idocHandler(IDOC_FAMILY.loiwcs)
@Injectable()
export class LoiwcsHandler implements IIdocHandler {
  /** Ordered list of LOIWCS configs; the first one whose `matches` returns true is used. */
  private static readonly configs: Array<IdocMappingConfig> = [
    LOIWCS_V3_CONFIG,
    LOIWCS_V2_CONFIG,
  ];

  /**
   * Select the appropriate LOIWCS config by evaluating each config's `matches`
   * predicate against the unwrapped IDOC node.
   * @param rawPayload - The raw IDoc payload.
   * @returns The first matching config, or `undefined` if none matches.
   */
  private static selectConfig(
    rawPayload: Record<string, unknown>,
  ): IdocMappingConfig | undefined {
    const idoc = IdocHandlerHelpers.getIdocNode(rawPayload);
    return LoiwcsHandler.configs.find((c) => !c.matches || c.matches(idoc));
  }

  /**
   * Validate a LOIWCS record has the required non-null fields.
   * sapObjectId, code and description are NOT NULL in the DB.
   * @param record - The DTO to validate.
   * @returns `true` if `sapObjectId`, `code`, and `description` are all present.
   */
  private static validate(record: IdocLoiwcsDto): boolean {
    return !!record.sapObjectId && !!record.code && !!record.description;
  }

  private readonly familyPattern = /loiwcs/i;

  private readonly metadata: IdocHandlerMetadata = {
    description: 'LOIWCS equipment data (supports v2 and v3 variants)',
    idocFamily: IDOC_FAMILY.loiwcs,
    version: 'generic',
  };

  public constructor(
    private readonly customLogger: AppLogger,
    private readonly loiwcsEquipmentService: LoiwcsEquipmentService,
  ) {}

  public canHandle(rawPayload: Record<string, unknown>): boolean {
    const context: JobsLogContext = {
      method: 'canHandle',
      service: 'LoiwcsHandler',
    };
    const idoc = IdocHandlerHelpers.getIdocNode(rawPayload);
    const ediDc40 = IdocHandlerHelpers.getNode(idoc['EDI_DC40']);
    const mestyp = ediDc40?.['MESTYP'];
    const result =
      typeof mestyp === 'string' && this.familyPattern.test(mestyp);
    this.customLogger.debug(
      `CanHandle result: ${result} (MESTYP=${mestyp})`,
      context,
    );
    return result;
  }

  private extract(rawPayload: Record<string, unknown>): Array<IdocLoiwcsDto> {
    const context: JobsLogContext = {
      method: 'extract',
      service: 'LoiwcsHandler',
    };
    this.customLogger.debug('Starting LOIWCS extraction', context);

    const config = LoiwcsHandler.selectConfig(rawPayload);
    if (!config) {
      this.customLogger.warn(
        'No matching LOIWCS config found for payload',
        context,
      );
      return [];
    }

    this.customLogger.debug(`Selected config: ${config.id}`, context);

    const records = extractIdocFields<IdocLoiwcsDto>(rawPayload, config);

    this.customLogger.debug(`Extracted ${records.length} records`, context);

    return records;
  }

  public getMetadata(): IdocHandlerMetadata {
    return this.metadata;
  }

  private async persist(records: Array<IdocLoiwcsDto>): Promise<void> {
    const context: JobsLogContext = {
      method: 'persist',
      service: 'LoiwcsHandler',
    };
    await Promise.all(
      records.map(async (record) => {
        if (!LoiwcsHandler.validate(record)) {
          this.customLogger.warn(
            `Invalid LOIWCS record, skipping: ${JSON.stringify(record)}`,
            context,
          );
          return;
        }
        await this.loiwcsEquipmentService.upsertEquipment(record);
      }),
    );
  }

  public async handle(rawPayload: Record<string, unknown>): Promise<void> {
    await this.persist(this.extract(rawPayload));
  }
}

