import { Injectable, OnModuleInit } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { EquipmentClass } from '@/idoc/modules/loiwcs/entities/equipment-class.entity';
import { EquipmentLevel } from '@/idoc/modules/loiwcs/entities/equipment-level.entity';
import { AppLogger } from '@/shared/logger/app-logger';

/**
 * Maps SAP VERWE usage indicator to the MES business codes used to look up
 * `isa95.equipment_level` and `isa95.equipment_class` at runtime.
 *
 * Add a new entry here to support a new VERWE value — no other code changes needed.
 *
 * SAP VERWE  │ equipment_level.code  │ equipment_class.code
 * ───────────┼───────────────────────┼─────────────────────
 *  0007      │ workCenter            │ workCenter
 *  LINE      │ productionLine        │ productionLine
 *  UAP       │ area                  │ uap
 */
const VERWE_TO_EQUIPMENT_CODES = new Map<
  string,
  { levelCode: string; classCode: string }
>([
  ['0007', { levelCode: 'workCenter', classCode: 'workCenter' }],
  ['LINE', { levelCode: 'productionLine', classCode: 'productionLine' }],
  ['UAP', { levelCode: 'area', classCode: 'uap' }],
]);

export interface ResolvedEquipmentIds {
  levelId: number;
  classId: number;
}

/**
 * Resolves a SAP VERWE indicator to the DB ids of the corresponding
 * `isa95.equipment_level` and `isa95.equipment_class` rows.
 *
 * IDs are cached in-memory after the first lookup so that repeated IDoc
 * processing does not generate extra DB round-trips for reference data.
 */
@Injectable()
export class EquipmentLevelResolverService implements OnModuleInit {
  private readonly levelCache = new Map<string, number>();

  private readonly classCache = new Map<string, number>();

  private readonly context = {
    method: '',
    service: EquipmentLevelResolverService.name,
  };

  public constructor(
    @InjectRepository(EquipmentLevel)
    private readonly equipmentLevelRepository: Repository<EquipmentLevel>,
    @InjectRepository(EquipmentClass)
    private readonly equipmentClassRepository: Repository<EquipmentClass>,
    private readonly customLogger: AppLogger,
  ) {}

  /**
   * Pre-warm the cache on startup so the first IDoc message never hits the DB
   * for reference data.
   */
  public async onModuleInit(): Promise<void> {
    const context = { ...this.context, method: 'onModuleInit' };
    try {
      const [levels, classes] = await Promise.all([
        this.equipmentLevelRepository.find({ select: ['id', 'code'] }),
        this.equipmentClassRepository.find({ select: ['id', 'code'] }),
      ]);

      for (const level of levels) {
        this.levelCache.set(level.code, level.id);
      }
      for (const cls of classes) {
        this.classCache.set(cls.code, cls.id);
      }

      this.customLogger.debug(
        `Cache warmed: ${levels.length} equipment levels, ${classes.length} equipment classes`,
        context,
      );
    } catch (error) {
      this.customLogger.warn(
        `Failed to pre-warm equipment level/class cache: ${(error as Error).message}`,
        context,
      );
    }
  }

  /**
   * Resolve a VERWE indicator to the DB ids of the corresponding
   * equipment level and equipment class.
   *
   * Falls back to a single DB lookup (and caches the result) when the code
   * is not yet in the cache (e.g., startup cache-warm failed).
   * @param verwe - The SAP VERWE value from the IDoc (e.g. '0007', 'LINE', 'UAP').
   * @returns The resolved level and class ids, or `undefined` when the VERWE value
   *          is not mapped or the corresponding reference row does not exist.
   */
  public async resolve(
    verwe: string,
  ): Promise<ResolvedEquipmentIds | undefined> {
    const context = { ...this.context, method: 'resolve' };
    const codes = VERWE_TO_EQUIPMENT_CODES.get(verwe.trim());

    if (!codes) {
      this.customLogger.warn(
        `No equipment codes configured for VERWE="${verwe}". ` +
          `Add an entry to VERWE_TO_EQUIPMENT_CODES to support this value.`,
        context,
      );
      return undefined;
    }

    const levelId = await this.resolveId(
      codes.levelCode,
      this.levelCache,
      this.equipmentLevelRepository,
      'equipment_level',
    );

    const classId = await this.resolveId(
      codes.classCode,
      this.classCache,
      this.equipmentClassRepository,
      'equipment_class',
    );

    if (!levelId || !classId) {
      this.customLogger.warn(
        `Could not resolve DB ids for VERWE="${verwe}" ` +
          `(levelCode="${codes.levelCode}" → ${levelId ?? 'NOT FOUND'}, ` +
          `classCode="${codes.classCode}" → ${classId ?? 'NOT FOUND'})`,
        context,
      );
      return undefined;
    }

    return { levelId, classId };
  }

  /**
   * Resolve a level code (e.g. `'plant'`) to its DB id using the in-memory cache,
   * with a DB fallback when the code was not present during startup cache-warm.
   * @param code - The `equipment_level.code` value to look up.
   * @returns The level id, or `undefined` when no matching row exists.
   */
  public async resolveLevelIdByCode(code: string): Promise<number | undefined> {
    return this.resolveId(
      code,
      this.levelCache,
      this.equipmentLevelRepository,
      'equipment_level',
    );
  }

  /**
   * Resolves an `isa95.equipment_class` id by its `code` column.
   * Cache-first with a DB fallback when the code was not present during startup cache-warm.
   * @param code - The `equipment_class.code` value to look up.
   * @returns The class id, or `undefined` when no matching row exists.
   */
  public async resolveClassIdByCode(code: string): Promise<number | undefined> {
    return this.resolveId(
      code,
      this.classCache,
      this.equipmentClassRepository,
      'equipment_class',
    );
  }

  private async resolveId(
    code: string,
    cache: Map<string, number>,
    repository: Repository<{ id: number; code: string }>,
    tableName: string,
  ): Promise<number | undefined> {
    const cached = cache.get(code);
    if (cached !== undefined) return cached;

    const row = await repository.findOne({
      where: { code },
      select: ['id', 'code'],
    });

    if (row) {
      cache.set(row.code, row.id);
      return row.id;
    }

    this.customLogger.warn(`No row found in ${tableName} for code="${code}"`, {
      ...this.context,
      method: 'resolveId',
    });
    return undefined;
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { trackSqlOperation } from '@/idoc/common/helpers/telemetry.helper';
import { Equipment } from '@/idoc/modules/common/entities/equipment.entity';
import { PropertySemanticsValidatorService } from '@/idoc/modules/common/property-semantics/property-semantics-validator.service';
import { IdocLoiwcsDto } from '@/idoc/modules/loiwcs/dto/idoc-loiwcs.dto';
import { EquipmentDescriptionByLanguage } from '@/idoc/modules/loiwcs/entities/equipment-description-by-language.entity';
import { EquipmentEquipmentClass } from '@/idoc/modules/loiwcs/entities/equipment-equipment-class.entity';
import { EquipmentProperty } from '@/idoc/modules/loiwcs/entities/equipment-property.entity';
import { EquipmentLevelResolverService } from '@/idoc/modules/loiwcs/service/equipment-level-resolver.service';
import { AppLogger } from '@/shared/logger/app-logger';

@Injectable()
export class LoiwcsEquipmentService {
  /** SAP VERWE value that identifies area-level (UAP) equipment. */
  private static readonly uapVerwe = 'UAP';

  /** `equipment_level.code` for the plant-level equipment row used as UAP parent. */
  private static readonly plantLevelCode = 'site';

  /** `equipment_class.code` for the plant-level equipment row used as UAP parent. */
  private static readonly plantClassCode = 'plant';

  /**
   * Build a JSON path for a given property key.
   * Uses simple dot notation for flat property access.
   * Extend to handle nested structures as needed.
   * @param key - Property key
   * @returns JSON path string (e.g., '$.propertyName')
   */
  private static buildJsonPath(key: string): string {
    return `$.${key}`;
  }

  /**
   * Build a JSON_MODIFY SQL expression that chains multiple JSON property updates.
   * Each property in `properties` is applied as a separate JSON_MODIFY call,
   * allowing database-side atomic merge without fetching and re-saving the entire row.
   *
   * Example output:
   * `JSON_MODIFY(JSON_MODIFY(properties_json, '$.prop1', @0), '$.prop2', JSON_QUERY(@1))`
   * @param baseExpression - Starting expression (e.g., 'properties_json' for update, '{}' for insert)
   * @param properties - Key/value pairs to apply via JSON_MODIFY
   * @returns SQL expression string and ordered parameters array
   */
  private static buildJsonModifyExpression(
    baseExpression: string,
    properties: Record<string, unknown>,
  ): { expression: string; parameters: Array<unknown> } {
    let expression = baseExpression;
    const parameters: Array<unknown> = [];

    for (const [key, value] of Object.entries(properties)) {
      if (value !== undefined) {
        const index = parameters.length;
        const path = LoiwcsEquipmentService.buildJsonPath(key);

        if (value !== null && typeof value === 'object') {
          parameters.push(JSON.stringify(value));
          expression = `JSON_MODIFY(${expression}, '${path}', JSON_QUERY(@${index}))`;
        } else {
          parameters.push(value);
          expression = `JSON_MODIFY(${expression}, '${path}', @${index})`;
        }
      }
    }

    return { expression, parameters };
  }

  private readonly context: JobsLogContext = {
    method: '',
    service: LoiwcsEquipmentService.name,
  };

  public constructor(
    @InjectRepository(Equipment)
    private readonly equipmentRepository: Repository<Equipment>,
    @InjectRepository(EquipmentDescriptionByLanguage)
    private readonly equipmentDescriptionRepository: Repository<EquipmentDescriptionByLanguage>,
    @InjectRepository(EquipmentEquipmentClass)
    private readonly equipmentEquipmentClassRepository: Repository<EquipmentEquipmentClass>,
    @InjectRepository(EquipmentProperty)
    private readonly equipmentPropertyRepository: Repository<EquipmentProperty>,
    private readonly levelResolver: EquipmentLevelResolverService,
    private readonly propertySemanticsValidator: PropertySemanticsValidatorService,
    private readonly customLogger: AppLogger,
  ) {}

  /**
   * Upsert `isa95.equipment` from a LOIWCS IDoc payload.
   *
   * Field mapping (using MES business term names from IdocLoiwcsDto):
   *  erpSource      → equipment.erp_source
   *  code           → equipment.code
   *  plant          → equipment.plant
   *  sapObjectId    → equipment.sap_obj_id
   *  description    → equipment_description_by_language.description
   *  equipmentLevel → equipment.equipment_level_id  (resolved dynamically via equipment_level.code)
   *                 → equipment_equipment_class.equipment_class_id (resolved dynamically via equipment_class.code)
   *  properties     → equipment_property.properties_json
   * @param payload - The LOIWCS DTO produced by the mapping engine.
   */
  public async upsertEquipment(payload: IdocLoiwcsDto): Promise<void> {
    const context = { ...this.context, method: 'upsertEquipment' };
    if (!payload) {
      this.customLogger.error('LOIWCS payload is empty', context);
      return;
    }

    const {
      code,
      description,
      plant: plantString,
      equipmentLevel,
      sapObjectId: sapObjectIdString,
      erpSource,
      properties,
    } = payload;

    const sapObjectId = Number(sapObjectIdString);
    if (!sapObjectIdString || Number.isNaN(sapObjectId)) {
      this.customLogger.error(
        `Invalid sapObjectId value "${sapObjectIdString}" — equipment not persisted`,
        context,
      );
      return;
    }

    const plant = Number(plantString);
    if (!plantString || Number.isNaN(plant)) {
      this.customLogger.error(
        `Invalid plant value "${plantString}" — equipment not persisted (sapObjectId=${sapObjectIdString})`,
        context,
      );
      return;
    }

    // 1. Resolve equipmentLevel → DB ids via dynamic DB lookup (cached after first access).
    if (!equipmentLevel) {
      this.customLogger.error(
        `Missing equipmentLevel — equipment not persisted (sapObjectId=${sapObjectIdString})`,
        context,
      );
      return;
    }
    const resolved = await this.levelResolver.resolve(equipmentLevel);
    if (!resolved) {
      this.customLogger.error(
        `Could not resolve equipmentLevel "${equipmentLevel}" to DB ids — equipment not persisted (sapObjectId=${sapObjectIdString})`,
        context,
      );
      return;
    }
    const { levelId, classId } = resolved;

    // For UAP-level equipment, resolve the parent plant-equipment id from the DB before
    // Entering the tracked SQL block so the lookup is not counted as part of the upsert span.
    const parentEquipmentId =
      equipmentLevel === LoiwcsEquipmentService.uapVerwe
        ? await this.resolveUapParentId(plant)
        : undefined;

    // TODO: Add database index on equipment.sap_obj_id (non-unique) to optimize this lookup.
    // SapObjId is not unique; multiple rows may exist with the same value.
    // Index will reduce table scan cost, though selection behavior (first result) remains unchanged.
    // 2–6. Find/insert/update equipment row plus related records, tracked as one SQL operation
    await trackSqlOperation('equipment', plantString ?? '', async () => {
      // Upsert by sapObjId: insert on first occurrence, update code/level/erpSource on repeat.
      const result = await this.equipmentRepository.upsert(
        {
          code: code ?? '',
          equipmentLevelId: levelId,
          erpSource: erpSource ?? 'SAP',
          plant,
          sapObjId: sapObjectId,
          updatedAt: () => 'SYSUTCDATETIME()',
          ...(parentEquipmentId !== undefined && { parentEquipmentId }),
        },
        { conflictPaths: ['sapObjId'] },
      );

      // Resolve the saved entity identity for subsequent relation/property writes.
      const savedId = result.identifiers[0]?.['id'] as number | undefined;

      // 3. Use resolved entity identity for subsequent relation/property writes.
      // Fallback lookup is retained only if ORM upsert did not return identity.
      // This lookup will also benefit from the proposed sapObjId index.
      const saved =
        savedId && plant
          ? { id: savedId, plant }
          : await this.equipmentRepository.findOne({
              where: { sapObjId: sapObjectId },
              select: ['id', 'plant'],
            });

      if (saved) {
        // 4. Upsert equipment_equipment_class
        await this.upsertEquipmentClass(saved.id, classId, saved.plant);
        // 5. Upsert English description
        if (description !== undefined) {
          await this.upsertDescription(saved.id, saved.plant, description);
        }

        // 6. Persist pre-mapped properties JSON (produced at mapping config level)
        if (properties && Object.keys(properties).length > 0) {
          await this.upsertProperties(
            saved.id,
            saved.plant,
            classId,
            properties,
          );
        }
      }
    });

    this.customLogger.debug(
      `Equipment upserted: sapObjectId=${sapObjectIdString}, code=${code}, equipmentLevel=${equipmentLevel} (levelId=${levelId}, classId=${classId})`,
      context,
    );
  }

  /**
   * Resolves the parent equipment id for a UAP-level item.
   * Looks up the plant-level `isa95.equipment` row whose `plant` column matches
   * the WERKS value from the IDoc, then returns its `id`.
   * @param plant - The numeric WERKS value from the IDoc.
   * @returns The DB id of the plant-level equipment, or `undefined` when not found.
   */
  private async resolveUapParentId(plant: number): Promise<number | undefined> {
    const context = { ...this.context, method: 'resolveUapParentId' };

    const [plantLevelId, plantClassId] = await Promise.all([
      this.levelResolver.resolveLevelIdByCode(
        LoiwcsEquipmentService.plantLevelCode,
      ),
      this.levelResolver.resolveClassIdByCode(
        LoiwcsEquipmentService.plantClassCode,
      ),
    ]);

    if (!plantLevelId) {
      this.customLogger.warn(
        `No equipment_level row found for code="${LoiwcsEquipmentService.plantLevelCode}" — UAP parentEquipmentId not set`,
        context,
      );
      return undefined;
    }

    if (!plantClassId) {
      this.customLogger.warn(
        `No equipment_class row found for code="${LoiwcsEquipmentService.plantClassCode}" — UAP parentEquipmentId not set`,
        context,
      );
      return undefined;
    }
    const plantEquipment = await this.equipmentRepository
      .createQueryBuilder('eq')
      .innerJoin(
        EquipmentEquipmentClass,
        'eec',
        'eec.equipment_id = eq.id AND eec.equipment_class_id = :plantClassId',
        { plantClassId },
      )
      .where('eq.plant = :plant AND eq.equipment_level_id = :plantLevelId', {
        plant,
        plantLevelId,
      })
      .select('eq.id')
      .getOne();

    if (!plantEquipment) {
      this.customLogger.warn(
        `No plant-level equipment found for plant=${plant} (levelCode=${LoiwcsEquipmentService.plantLevelCode}, classCode=${LoiwcsEquipmentService.plantClassCode}) — UAP parentEquipmentId not set`,
        context,
      );
      return undefined;
    }

    return plantEquipment.id;
  }

  /**
   * Insert or update the equipment_equipment_class record for an equipment.
   * Idempotent: updates the class id if it changed, skips if already correct.
   * @param equipmentId - The internal DB id of the equipment row.
   * @param equipmentClassId - The resolved class id derived from VERWE.
   * @param plant - The plant number used when inserting a new record.
   * @returns A promise that resolves when the upsert is complete.
   */
  private async upsertEquipmentClass(
    equipmentId: number,
    equipmentClassId: number,
    plant: number,
  ): Promise<void> {
    const existing = await this.equipmentEquipmentClassRepository.findOne({
      where: { equipmentId },
    });

    if (existing) {
      if (existing.equipmentClassId !== equipmentClassId) {
        await this.equipmentEquipmentClassRepository.update(
          { id: existing.id },
          { equipmentClassId },
        );
      }
    } else {
      await this.equipmentEquipmentClassRepository.insert({
        plant,
        equipmentId,
        equipmentClassId,
      });
    }
  }

  /**
   * Validate, then upsert the equipment_property JSON blob for an equipment row.
   *
   * Each key in `properties` is treated as an `equipment_class_property.code`.
   * Values are validated against the semantics metadata before being persisted.
   * Invalid properties are logged and excluded; the rest are merged with any
   * existing stored properties using database-side JSON_MODIFY operations.
   *
   * See IDOC_DYNAMIC_MAPPING.md § LoiwcsEquipmentService for the full validation flow.
   * @param equipmentId - The internal DB id of the equipment row.
   * @param plant - The plant number used when inserting a new record.
   * @param equipmentClassId - The resolved class id derived from VERWE.
   * @param properties - Key/value pairs to persist in the properties JSON blob.
   * @returns A promise that resolves when the upsert is complete.
   */
  private async upsertProperties(
    equipmentId: number,
    plant: number,
    equipmentClassId: number,
    properties: Record<string, unknown>,
  ): Promise<void> {
    if (Object.keys(properties).length === 0) return;

    const context = { ...this.context, method: 'upsertProperties' };

    // Validate each property against equipment_class_property semantics.
    // Run validations in parallel then collect the valid subset.
    const validationResults = await Promise.all(
      Object.entries(properties).map(async ([code, value]) => {
        if (value === undefined) {
          return {
            code,
            value,
            result: {
              valid: false,
              errors: ['Value is undefined'],
            },
          };
        }

        const result = await this.propertySemanticsValidator.validate({
          code,
          equipmentClassId,
          value,
        });
        return { code, value, result };
      }),
    );

    const validProperties: Record<string, unknown> = {};
    for (const { code, value, result } of validationResults) {
      if (result.valid) {
        validProperties[code] = value;
      } else {
        this.customLogger.warn(
          `Property "${code}" failed semantics validation for equipmentClassId=${equipmentClassId} — skipped. Errors: ${result.errors.join('; ')}`,
          context,
        );
      }
    }

    if (Object.keys(validProperties).length === 0) {
      this.customLogger.warn(
        `All properties failed validation for equipmentId=${equipmentId}, equipmentClassId=${equipmentClassId} — nothing persisted`,
        context,
      );
      return;
    }

    const existing = await this.equipmentPropertyRepository.findOne({
      where: { equipmentId, equipmentClassId },
      select: ['id'],
    });

    // Build JSON_MODIFY expression for database-side merge
    const { expression, parameters } =
      LoiwcsEquipmentService.buildJsonModifyExpression(
        existing ? 'properties_json' : "'{}'",
        validProperties,
      );

    if (parameters.includes(undefined)) {
      this.customLogger.warn(
        `Skipping property upsert because generated SQL parameters contain undefined values for equipmentId=${equipmentId}, equipmentClassId=${equipmentClassId}`,
        context,
      );
      return;
    }

    if (existing) {
      const updateParameters = [...parameters, existing.id];

      await this.equipmentPropertyRepository.manager.query(
        `
        UPDATE [isa95].[equipment_property]
        SET properties_json = ${expression},
            updated_at = SYSUTCDATETIME()
        WHERE id = @${parameters.length}
        `,
        updateParameters,
      );

      return;
    }

    const insertParameters = [
      ...parameters,
      plant,
      equipmentId,
      equipmentClassId,
    ];
    const plantIndex = parameters.length;
    const equipmentIdIndex = plantIndex + 1;
    const equipmentClassIdIndex = plantIndex + 2;

    await this.equipmentPropertyRepository.manager.query(
      `
      INSERT INTO [isa95].[equipment_property]
      (
        plant,
        equipment_id,
        equipment_class_id,
        properties_json,
        created_at,
        updated_at
      )
      VALUES (
        @${plantIndex},
        @${equipmentIdIndex},
        @${equipmentClassIdIndex},
        ${expression},
        SYSUTCDATETIME(),
        SYSUTCDATETIME()
      )
      `,
      insertParameters,
    );
  }

  /**
   * Insert or update the English description for an equipment row in
   * `isa95.equipment_description_by_language`.
   * Uses language code 'EN' for all records.
   * @param equipmentId - The internal DB id of the equipment row.
   * @param plant - The plant number.
   * @param description - The description text (from E1CRTXL.KTEXT).
   * @returns A promise that resolves when the upsert is complete.
   */
  private async upsertDescription(
    equipmentId: number,
    plant: number,
    description: string,
  ): Promise<void> {
    await this.equipmentDescriptionRepository.upsert(
      {
        code: 'EN',
        description,
        equipmentId,
        plant,
        updatedAt: () => 'SYSUTCDATETIME()',
      },
      {
        conflictPaths: ['equipmentId', 'code'],
      },
    );
  }
}

/**
 * Typed output produced by the MDM_EQUIPMENT_SAVEREPLICA mapping engine.
 * Field names use business terms corresponding to PhysicalAsset entity fields.
 *
 * Segment mapping:
 *  EDI_DC40.SNDPOR                           → erpSource      (normalised by 'erpSource' transform)
 *  E1BP_IEQM_EXTRACTOR.EQUIPMENT_INT         → code           (with 'removeLeadingZeros' transform)
 *  E1BP_IEQM_EXTRACTOR.DESCRIPT             → description
 *  E1BP_IEQM_EXTRACTOR.PLANPLANT            → plant
 *  E1BP_IEQM_EXTRACTOR.READ_FLOC            → physicalAssetLocation
 *  E1BP_IEQM_EXTRACTOR.FREE_NUM1            → freeNum1       (used for date derivation)
 */
export class MdmEquipmentSavereplicaDto {
  /** Derived from EDI_DC40.SNDPOR — 3-char ERP source identifier (e.g. "FC1") */
  public erpSource?: string;

  /** E1BP_IEQM_EXTRACTOR.EQUIPMENT_INT — equipment code with leading zeros removed */
  public code?: string;

  /** E1BP_IEQM_EXTRACTOR.DESCRIPT — equipment description */
  public description?: string;

  /** E1BP_IEQM_EXTRACTOR.PLANPLANT — plant number as string */
  public plant?: string;

  /** E1BP_IEQM_EXTRACTOR.READ_FLOC — physical asset location */
  public physicalAssetLocation?: string;

  /** E1BP_IEQM_EXTRACTOR.FREE_NUM1 — status indicator for date derivation */
  public freeNum1?: string;
}

