 *
 * Table: isa95.physical_asset
 */
@Entity({ name: 'physical_asset', schema: 'isa95' })
@Unique('uq_physical_asset_plant_code', ['plant', 'code'])
export class PhysicalAsset extends TimeStamp {
  @PrimaryGeneratedColumn({ name: 'id' })
  public id: number;

  /**
   * Plant identifier (from PLAN_PLANT).
   */
  @Column({
    name: 'plant',
    nullable: false,
    type: 'smallint',
  })
  public plant: number;

  /**
   * Equipment code (from EQUIPMENT_INT after removing leading zeros).
   * Used as a matching key along with plant.
   */
  @Column({
    length: 18,
    name: 'code',
    nullable: false,
    type: 'nvarchar',
  })
