  /**
   * Physical asset location (from READ_FLOC field).
   * Represents the functional location or physical location of the asset.
   */
  @Column({
    length: 30,
    name: 'physical_asset_location',
    nullable: true,
    type: 'nvarchar',
  })
  public physicalAssetLocation: string;

  /**
   * Effective start date for this physical asset definition.
   * Derived from FREE_NUM1 field:
   *   - FREE_NUM1 = 0: Start = now (current timestamp)
   *   - FREE_NUM1 = 000009999: Use existing start date or now if not set
   *   - FREE_NUM1 = 000005555 or other: Start = null (no validity period)
   */
  @Column({
    name: 'effective_start_date',
    nullable: true,
    type: 'date',
  })
  public effectiveStartDate: Date | null;

  /**
   * Effective end date for this physical asset definition.
   * Derived from FREE_NUM1 field:
   *   - FREE_NUM1 = 0: End = 9999-12-31 (active/no end date)
   *   - FREE_NUM1 = 000009999: End = now (current timestamp, equipment is deactivated)
   *   - FREE_NUM1 = 000005555 or other: End = null (no validity period)
   */
  @Column({
    name: 'effective_end_date',
    nullable: true,
    type: 'date',
  })
  public effectiveEndDate: Date | null;

  /**
   * ERP source identifier (derived, e.g. 'FC1').
   * Indicates which ERP system provided this data.
   */
  @Column({
    length: 3,
    name: 'erp_source',
    nullable: false,
    type: 'char',
  })
  public erpSource: string;

