    () => PhysicalAssetDescriptionByLanguage,
    (description) => description.physicalAsset,
  )
  public descriptions: Array<PhysicalAssetDescriptionByLanguage>;
}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { MDM_EQUIPMENT_SAVEREPLICA_CONFIG } from '@/idoc/common/config/idoc-mapping-configs';
import { IdocHandlerHelpers } from '@/idoc/common/helpers/idoc-handler.helpers';
import {
  extractIdocFields,
  IdocMappingConfig,
} from '@/idoc/common/helpers/idoc-mapper-engine';
import {
  idocHandler,
  IIdocHandler,
  IdocHandlerMetadata,
  IDOC_FAMILY,
} from '@/idoc/idoc-events/message-handler.interface';
import { MdmEquipmentSavereplicaDto } from '@/idoc/modules/mdm-equipment-savereplica/dto/mdm-equipment-savereplica.dto';
import { MdmEquipmentSavereplicaService } from '@/idoc/modules/mdm-equipment-savereplica/service/mdm-equipment-savereplica.service';
import { AppLogger } from '@/shared/logger/app-logger';

/**
 * MDM_EQUIPMENT_SAVEREPLICA handler — physical asset master data.
 *
 * Processes IDoc payloads containing equipment master data and maps them to
 * physical asset definition records with support for effective date derivation.
 */
@idocHandler(IDOC_FAMILY.mdmEquipmentSavereplica)
@Injectable()
export class MdmEquipmentSavereplicaHandler implements IIdocHandler {
  /** Ordered list of configs for this handler; typically just one config. */
  private static readonly configs: Array<IdocMappingConfig> = [
    MDM_EQUIPMENT_SAVEREPLICA_CONFIG,
  ];

  /**
   * Select the appropriate config by evaluating each config's `matches`
   * predicate against the unwrapped IDOC node.
   * @param rawPayload - The raw IDoc payload.
   * @returns The first matching config, or `undefined` if none matches.
   */
  private static selectConfig(
    rawPayload: Record<string, unknown>,
  ): IdocMappingConfig | undefined {
    const idoc = IdocHandlerHelpers.getIdocNode(rawPayload);
    return MdmEquipmentSavereplicaHandler.configs.find(
      (c) => !c.matches || c.matches(idoc),
    );
  }

  /**
   * Validate a MDM_EQUIPMENT_SAVEREPLICA record has the required fields.
   * code and plant are mandatory.
   * @param record - The DTO to validate.
   * @returns `true` if `code` and `plant` are both present.
   */
  private static validate(record: MdmEquipmentSavereplicaDto): boolean {
    return !!record.code && !!record.plant;
  }

  private readonly familyPattern = /mdm.*equipment|equipment.*replica/i;

  private readonly metadata: IdocHandlerMetadata = {
    description: 'MDM_EQUIPMENT_SAVEREPLICA physical asset master data',
    idocFamily: IDOC_FAMILY.mdmEquipmentSavereplica,
    version: 'generic',
  };

  public constructor(
    private readonly customLogger: AppLogger,
    private readonly savereplicaService: MdmEquipmentSavereplicaService,
  ) {}

  public canHandle(rawPayload: Record<string, unknown>): boolean {
    const context: JobsLogContext = {
      method: 'canHandle',
      service: 'MdmEquipmentSavereplicaHandler',
    };
    const idoc = IdocHandlerHelpers.getIdocNode(rawPayload);
    const ediDc40 = IdocHandlerHelpers.getNode(idoc['EDI_DC40']);
    const mestyp = ediDc40?.['MESTYP'];
    const result =
      typeof mestyp === 'string' && this.familyPattern.test(mestyp);
    this.customLogger.debug(
      `CanHandle result: ${result} (MESTYP=${mestyp})`,
      context,
    );
    return result;
  }

  private extract(
    rawPayload: Record<string, unknown>,
  ): Array<MdmEquipmentSavereplicaDto> {
    const context: JobsLogContext = {
      method: 'extract',
      service: 'MdmEquipmentSavereplicaHandler',
    };
    this.customLogger.debug(
      'Starting MDM_EQUIPMENT_SAVEREPLICA extraction',
      context,
    );

    const config = MdmEquipmentSavereplicaHandler.selectConfig(rawPayload);
    if (!config) {
      this.customLogger.warn(
        'No matching MDM_EQUIPMENT_SAVEREPLICA config found for payload',
        context,
      );
      return [];
    }

    this.customLogger.debug(`Selected config: ${config.id}`, context);

    const records = extractIdocFields<MdmEquipmentSavereplicaDto>(
      rawPayload,
      config,
    );

    this.customLogger.debug(`Extracted ${records.length} records`, context);

    return records;
  }

  public getMetadata(): IdocHandlerMetadata {
    return this.metadata;
  }

  private async persist(
    records: Array<MdmEquipmentSavereplicaDto>,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'persist',
      service: 'MdmEquipmentSavereplicaHandler',
    };
    await Promise.all(
      records.map(async (record) => {
        if (!MdmEquipmentSavereplicaHandler.validate(record)) {
          this.customLogger.warn(
            `Invalid MDM_EQUIPMENT_SAVEREPLICA record, skipping: ${JSON.stringify(record)}`,
            context,
          );
          return;
        }
        await this.savereplicaService.upsertPhysicalAsset(record);
      }),
    );
  }

  public async handle(rawPayload: Record<string, unknown>): Promise<void> {
    await this.persist(this.extract(rawPayload));
  }
}

