/**
 * Effective date derivation rules based on FREE_NUM1 field:
 *
 * All dates are normalized to yyyy-mm-dd semantics with the time portion
 * set to UTC midnight before being persisted as Date values.
 *
 * Case 1: FREE_NUM1 = '0' (ACTIVE)
 *   Effective Start Date = today (yyyy-mm-dd)
 *   Effective End Date = 9999-12-31
 *
 * Case 2: FREE_NUM1 = '000009999' (DEACTIVATED)
 *   If updating existing record: startDate = preserve (undefined), endDate = today
 *     Effective Start Date = preserved (unchanged)
 *     Effective End Date = today (yyyy-mm-dd)
 *   If creating new record:
 *     Effective Start Date = today (yyyy-mm-dd)
 *     Effective End Date = today (yyyy-mm-dd)
 *
 * Case 3: FREE_NUM1 = '000005555' or other values (NO VALIDITY PERIOD)
 *   Effective Start Date = null
 *   Effective End Date = null
 */
@Injectable()
export class MdmEquipmentSavereplicaService {
  /** Sentinel values for active equipment */
  private static readonly activeStatuses = new Set(['0', '000000000']);

  /** Sentinel value for deactivated equipment */
  private static readonly deactivatedStatus = '000009999';

  /** Sentinel value for equipment with no validity period */
  private static readonly noValidityStatus = '000005555';

  /** Default end date for active equipment in yyyy-mm-dd format. */
  private static readonly defaultActiveEndDate = new Date(
    Date.UTC(9999, 11, 31),
  );

  /**
   * Normalize a Date to a UTC date-only value.
   * @param date - The Date to normalize, or undefined
   * @returns Date truncated to UTC midnight, or undefined
   */
  private static normalizeToDateOnly(date?: Date): Date | undefined {
    if (!date) {
      return undefined;
    }

    return new Date(
      Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()),
    );
  }

  /**
   * Derive effective dates based on FREE_NUM1 status indicator.
   *
   * Returns an object with `startDate` and `endDate` properties as date-only values:
   * - If FREE_NUM1 = '0' (active): startDate = today, endDate = 9999-12-31
   * - If FREE_NUM1 = '000009999' (deactivated):
   *   - If existingRecord provided: startDate = preserve (undefined), endDate = today
   *   - If no existingRecord: startDate = today, endDate = today
   * - Otherwise: startDate = undefined, endDate = undefined (no validity)
   * @param freeNumber1 - The FREE_NUM1 field value from the IDoc
   * @param existingRecord - Optional existing record to preserve startDate from (deactivation case)
   * @returns Object with { startDate?, endDate? } as date-only Date values or undefined
   */
  private static deriveEffectiveDates(
    freeNumber1?: string,
    existingRecord?: PhysicalAsset | null,
  ): {
    startDate?: Date | null;
    endDate?: Date | null;
  } {
    const today = MdmEquipmentSavereplicaService.normalizeToDateOnly(
      new Date(),
    );
    const normalizedStatus = freeNumber1?.trim();

    if (
      MdmEquipmentSavereplicaService.activeStatuses.has(normalizedStatus ?? '')
    ) {
      return {
        startDate: today,
        endDate: MdmEquipmentSavereplicaService.defaultActiveEndDate,
      };
    }

    if (normalizedStatus === MdmEquipmentSavereplicaService.deactivatedStatus) {
      if (existingRecord?.effectiveStartDate) {
        return { endDate: today };
      }

      return {
        startDate: today,
        endDate: today,
      };
    }

    if (normalizedStatus === MdmEquipmentSavereplicaService.noValidityStatus) {
      return { startDate: null, endDate: null };
    }

    // Case 3: No validity period or unknown status
    return { startDate: null, endDate: null };
  }

  private readonly context: JobsLogContext = {
    method: '',
    service: MdmEquipmentSavereplicaService.name,
  };

  public constructor(
    @InjectRepository(PhysicalAsset)
    private readonly assetRepository: Repository<PhysicalAsset>,
    @InjectRepository(PhysicalAssetDescriptionByLanguage)
    private readonly assetDescriptionRepository: Repository<PhysicalAssetDescriptionByLanguage>,
    private readonly customLogger: AppLogger,
  ) {}

  /**
   * Insert or update the English description for a physical asset row in
   * `isa95.physical_asset_description_by_language`.
   * Uses language code 'EN' for all records. Ensures multi-language descriptions are
   * preserved for other languages when updating a single language.
   * @param physicalAssetId - The internal DB id of the physical asset row.
   * @param plant - The plant number.
   * @param description - The description text.
   * @returns A promise that resolves when the upsert is complete.
   */
  private async upsertDescription(
    physicalAssetId: number,
    plant: number,
    description: string,
  ): Promise<void> {
    await this.assetDescriptionRepository.upsert(
      {
        code: 'EN',
        description,
        physicalAssetId,
        plant,
        updatedAt: () => 'SYSUTCDATETIME()',
      },
      {
        conflictPaths: ['physicalAssetId', 'code'],
      },
    );
  }

  /**
   * Upsert physical asset definition from MDM_EQUIPMENT_SAVEREPLICA IDoc payload.
   * Field mapping:
   * erpSource              → physical_asset_definition.erp_source
   * code                   → physical_asset_definition.code (used as match key)
   * plant                  → physical_asset_definition.plant (used as match key)
   * description            → physical_asset_description_by_language.description (language code 'EN')
   * physicalAssetLocation  → physical_asset_definition.physical_asset_location
   * freeNum1               → effective date derivation
   * Upsert Logic:
   * - Match on: code + plant (must both be present)
   * - INSERT if not found
   * - UPDATE if found: update physicalAssetLocation, effective dates, erpSource
   * - Descriptions are stored separately in physical_asset_description_by_language to support
   *   multi-language descriptions without duplication. Existing descriptions for other
   *   languages are preserved when updating.
   * @param payload - The DTO produced by the mapping engine
   * @returns A promise that resolves when the upsert is complete.
   */
  public async upsertPhysicalAsset(
    payload: MdmEquipmentSavereplicaDto,
  ): Promise<void> {
    const context = { ...this.context, method: 'upsertPhysicalAsset' };

    if (!payload) {
      this.customLogger.error(
        'MDM_EQUIPMENT_SAVEREPLICA payload is empty',
        context,
      );
      return;
    }

    const {
      code,
      plant: plantString,
      description,
      physicalAssetLocation,
      erpSource,
      freeNum1,
    } = payload;

    // Validate mandatory fields
    if (!code) {
      this.customLogger.error(
        'Missing code in MDM_EQUIPMENT_SAVEREPLICA payload — asset not persisted',
        context,
      );
      return;
    }

    const plant = Number(plantString);
    if (!plantString || Number.isNaN(plant)) {
      this.customLogger.error(
        `Invalid plant value "${plantString}" — asset not persisted (code=${code})`,
        context,
      );
      return;
    }

    let savedAssetId: number | undefined;

    await trackSqlOperation(
      'physical_asset_definition',
      plantString,
      async () => {
        // Check if record exists
        const existing = await this.assetRepository.findOne({
          where: { code, plant },
        });

        // Derive effective dates (pass existing record for deactivation case handling)
        const { startDate, endDate } =
          MdmEquipmentSavereplicaService.deriveEffectiveDates(
            freeNum1,
            existing,
          );

        if (existing) {
          // UPDATE existing record
          const updateData: Partial<PhysicalAsset> = {
            effectiveEndDate: endDate,
            erpSource: erpSource ?? 'SAP',
            physicalAssetLocation,
          };

          // Update start date if explicitly derived (for active case or new deactivations)
          if (startDate !== undefined) {
            updateData.effectiveStartDate = startDate;
          }

          await this.assetRepository.update({ code, plant }, updateData);
          savedAssetId = existing.id;

          this.customLogger.debug(
            `Updated physical asset: code=${code}, plant=${plant}, startDate=${startDate?.toISOString().slice(0, 10) ?? 'preserved'}, endDate=${endDate?.toISOString().slice(0, 10) ?? 'null'}`,
            context,
          );
        } else {
          // INSERT new record
          const result = await this.assetRepository.insert({
            code,
            effectiveEndDate: endDate,
            effectiveStartDate: startDate,
            erpSource: erpSource ?? 'SAP',
            physicalAssetLocation,
            plant,
          });

          savedAssetId = result.identifiers[0]?.['id'] as number | undefined;

          this.customLogger.debug(
            `Inserted new physical asset: code=${code}, plant=${plant}, startDate=${startDate?.toISOString().slice(0, 10) ?? 'null'}, endDate=${endDate?.toISOString().slice(0, 10) ?? 'null'}`,
            context,
          );
        }
      },
    );

    // 4. Upsert description in physical_asset_description_by_language
    if (savedAssetId !== undefined && description !== undefined) {
      await this.upsertDescription(savedAssetId, plant, description);
    }
  }
}

/**
 *
 */
export async function startApp(): Promise<void> {
  const { NestFactory } = await import('@nestjs/core');
  const express = await import('express');
  const { IdocAppModule } = await import('./idoc-app.module');

  const app = await NestFactory.create(IdocAppModule, {
    rawBody: true,
  });

  app.use(express.json({ type: 'application/json' }));
  app.use(express.json({ type: 'application/cloudevents+json' }));
  app.enableShutdownHooks();

  await app.listen(3000);
}

