import {
  JobsLogContext,
  telemetryMetrics,
  PROCESSING_STATUS,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Plant } from './plant.entity';
import { EventhubService } from '@/shared/config/eventhub/eventhub.service';
import { AppLogger } from '@/shared/logger/app-logger';
import { EwmPlantMessage } from '@/shared/publish-message/interface/publish-event-ewm-plant';
import { PublishMessageService } from '@/shared/publish-message/publish-message.service';
import { PlantsResponseDto } from '@/shared/subscribe/dtos/plant.response.dto';

@Injectable()
export class PlantService {
  private readonly context: JobsLogContext = {
    method: '',
    service: PlantService.name,
  };

  public constructor(
    @InjectRepository(Plant)
    private readonly plantRepository: Repository<Plant>,
    private readonly customLogger: AppLogger,
    private readonly publishMessageService: PublishMessageService,
    private readonly eventhubService: EventhubService,
  ) {}

  @OnEvent('plant.c')
  private async create(payload: Plant): Promise<void> {
    this.context.method = 'create';
    if (!payload)
      return this.customLogger.error(
        `payload is empty ${payload}`,
        this.context,
      );
    try {
      const { ...plantData } = payload;
      const sqlStartTime = Date.now();
      await this.plantRepository.upsert(
        { ...plantData, updatedAt: () => 'SYSUTCDATETIME()' },
        { conflictPaths: ['plantId'] },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plantId),
        'plant',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plantId),
        'plant',
      );
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base and publish message : ${error.message}`,
        this.context,
        error.stack,
      );
    }
    return undefined;
  }

  @OnEvent('plant.u')
  private async updateByPlant(payload: Plant): Promise<void> {
    this.context.method = 'updateByPlant';
    const { plantId, ...plantData } = payload;

    if (!payload) {
      this.customLogger.error(
        'Invalid payload: missing plantId or plant data',
        this.context,
      );
      return;
    }

    try {
      const oldPlant = await this.plantRepository.findOne({
        where: { plantId },
      });
      const isBufferization = oldPlant
        ? oldPlant.bufferization !== payload.bufferization
        : false;
      const sqlStartTime = Date.now();
      await this.plantRepository.upsert(
        {
          plantId,
          ...plantData,
          updatedAt: () => 'SYSUTCDATETIME()',
        }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['plantId'] },
      );
      if (isBufferization) {
        const ewmPlantMessage: EwmPlantMessage = {
          message: 'plant hierarchy data ingestion Plant updated',
        };
        await this.publishMessageService.publishMessage(
          this.eventhubService.topicEwmPlants,
          ewmPlantMessage,
        );
      }
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plantId),
        'plant',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plantId),
        'plant',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating plant: ${error.message}`,
        this.context,
      );
    }
  }

  @OnEvent('plant.r')
  private async readSnapshot(payload: Plant): Promise<void> {
    this.context.method = 'readSnapshot';
    if (!payload)
      return this.customLogger.error(
        `payload is empty${payload}`,
        this.context,
      );

    try {
      const { plantId, ...plantData } = payload;
      const sqlStartTime = Date.now();
      await this.plantRepository.upsert(
        {
          plantId,
          ...plantData,
          updatedAt: () => 'SYSUTCDATETIME()',
        }, // Needed because upsert() does not care about the decorator @UpdateDateColumn
        { conflictPaths: ['plantId'] },
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(payload.plantId),
        'plant',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(payload.plantId),
        'plant',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating plant: ${error.message}`,
        this.context,
      );
    }
    return undefined;
  }

  public async getPlants(): Promise<Array<PlantsResponseDto>> {
    this.context.method = 'getPlants';
    try {
      const result: Array<Plant> = await this.plantRepository.find({
        select: ['plantId', 'languageCode', 'timezone', 'plantLink'],
      });
      const plantDtos: Array<PlantsResponseDto> = result.map((plant) => ({
        languageCode: plant.languageCode,
        plantId: plant.plantId,
        plantLink: plant.plantLink,
        timeZone: plant.timezone,
      }));

      return plantDtos;
    } catch (error) {
      this.customLogger.error(
        `Error fetching plants: ${error.message}`,
        this.context,
      );
      throw error;
    }
  }
}

