@Module({
  exports: [SubscribeMessageService],
  imports: [ConfigModule, PlantModule, RedisConfigModule, DaprConfigModule],
  providers: [SubscribeMessageService],
})
export class SubscribeModule {}

import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { AppLogger } from '../logger/app-logger';
import { RedisConfigService } from '@/shared/config/redis/redis-store/redis-store.service';
import { PlantService } from '@/shared/plant/plant.service';
import { PlantsResponseDto } from '@/shared/subscribe/dtos/plant.response.dto';
import { SubscribeResponseDto } from '@/shared/subscribe/dtos/subscribe.response.dto';

@Injectable()
export class SubscribeMessageService {
  private readonly daprClient: DaprClient;

  public constructor(
    private readonly redisConfigService: RedisConfigService,
    private readonly plantService: PlantService,
    private readonly customLogger: AppLogger,
  ) {
    this.daprClient = new DaprClient();
  }

  public async handleMessage(message: SubscribeResponseDto): Promise<void> {
    const context: JobsLogContext = {
      method: 'handleMessage',
      service: 'SubscribeMessageService',
    };
    try {
      this.customLogger.debug(
        `====== Received Message ========== ${JSON.stringify(message)}`,
        context,
      );
      const plants = await this.fetchPlant();
      await this.savePlantsInRedis(plants);
    } catch (error) {
      this.customLogger.error(
        `Error processing message: ${error}`,
        context,
        error.stack,
      );
    }
  }

  public async savePlantsInRedis(
    plants: Array<PlantsResponseDto>,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'savePlantsInRedis',
      service: 'SubscribeMessageService',
    };
    try {
      const { redisPlantKey, redisStoreAmr } = this.redisConfigService;

      const dataToCache = {
        key: redisPlantKey,
        value: [plants],
      };

      await this.daprClient.state.save(redisStoreAmr, [dataToCache]);
    } catch (error) {
      this.customLogger.error(
        `Error saving list of plant in Redis: ${error}`,
        context,
        error.stack,
      );
    }
  }

  public async fetchPlant(): Promise<Array<PlantsResponseDto>> {
    const context: JobsLogContext = {
      method: 'fetchPlant',
      service: 'SubscribeMessageService',
    };
    try {
      const plants = await this.plantService.getPlants();
      return plants;
    } catch (error) {
      this.customLogger.error(
        `Error fetching plants: ${error}`,
        context,
        error.stack,
      );
      throw new Error('Invalid response from fetch plant');
    }
  }
}

/**
 * Default catch function that returns the error as the specified type.
 * @param error - The error caught in the try block.
 * @returns The error cast to the specified type.
 */
function defaultCatchFunction<TError>(error: Error): TError {
  return error as unknown as TError;
}

/**
 * A utility function that wraps try-catch logic in a consistent return format.
 *
 * This function can be called either with a function:
 * `asyncTryCatch(() => Promise<T>)`
 *
 * Or with an object containing `tryFn` and an optional `catchFn`:
 * `asyncTryCatch({ tryFn: () => Promise<T>, catchFn?: (err) => TError })`
 * @param optionsOrTryFunction - Either a function to execute, or an object with `tryFn` (required) and `catchFn` (optional).
 * @returns A tuple: [result or undefined, error or undefined].
 */
export async function asyncTryCatch<T, TError = Error>(
  optionsOrTryFunction:
    | (() => Promise<T>)
    | {
        /**
         * The function to attempt execution of.
         */
        tryFn: () => Promise<T>;

        /**
         * Optional catch handler to customize the returned error.
         */
        catchFn?: (error: Error) => Promise<TError> | TError;
      },
): Promise<[T | undefined, TError | undefined]> {
  try {
    if (typeof optionsOrTryFunction === 'function') {
      return [await optionsOrTryFunction(), undefined];
    }

    return [await optionsOrTryFunction.tryFn(), undefined];
  } catch (error_) {
    const error = error_ instanceof Error ? error_ : new Error(String(error_));
    const catchFunction =
      typeof optionsOrTryFunction !== 'function' && optionsOrTryFunction.catchFn
        ? optionsOrTryFunction.catchFn
        : defaultCatchFunction;

    return [undefined, await catchFunction(error)];
  }
}

import { randomInt } from 'node:crypto';
import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '@/shared/logger/app-logger';

/**
 * Calculates the delay for the next retry attempt using exponential backoff with a random jitter.
 * @param attempt - The current attempt number.
 * @param maxBackoff - The maximum backoff time in seconds.
 * @returns The calculated delay in milliseconds.
 */
export function calculateExponentialBackoffDelay(
  attempt: number,
  maxBackoff: number,
): number {
  const randomNumberMilliseconds = randomInt(0, 1000); // Random number between 0 and 1000
  const exponentialDelay = 2 ** attempt; // 2^n
  return Math.min(
    exponentialDelay * 1000 + randomNumberMilliseconds,
    maxBackoff * 1000,
  ); // Convert seconds to milliseconds
}

/**
 * Retries a given operation a specified number of times with an exponential backoff delay between attempts.
 * @template T The type of the result returned by the operation.
 * @param logger - Logger instance for logging.
 * @param context Job Log Context
 * @param operation - The operation to retry.
 * @param [retries] - Number of retry attempts.
 * @param [baseDelayMs] - Base delay between retries in milliseconds.
 * @param [jitter] - Whether to add randomness to the delay.
 * @param [attempt] - Current attempt number.
 * @param maxBackoff -max delay
 * @param customRetryableCheck - Optional predicate to override the default retryable-error detection.
 * @returns A promise that resolves to the result of the operation.
 * @throws Will throw an error if the operation fails after the specified number of retries.
 */
export async function exponentialBackoffRetry<T>(
  logger: AppLogger,
  context: JobsLogContext,
  operation: () => Promise<T>,
  retries = 5,
  baseDelayMs = 1000,
  jitter = true,
  attempt = 1,
  maxBackoff = 32,
  customRetryableCheck?: (error: Error) => boolean,
): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    const normalizedError = error as Error & {
      code?: number;
      message?: string;
      name?: string;
    };
    const message = normalizedError.message ?? '';
    const { code } = normalizedError;

    const defaultRetryableError =
      // If Redis returns a 5xx-like error (this would depend on the client you're using)
      code === 429 ||
      (typeof code === 'number' && code >= 500 && code < 600) ||
      message.includes('The client is closed') ||
      // Network or connection errors (Socket closed in case of redis infra redeploy)
      message.includes('Socket closed unexpectedly') ||
      // Network or connection errors (AbortError)
      normalizedError.name === 'AbortError' ||
      // Redis errors that indicate retryable conditions
      (normalizedError.name === 'ReplyError' &&
        (message.includes('TRYAGAIN') || message.includes('READONLY')));

    const isRetryableError = customRetryableCheck
      ? customRetryableCheck(normalizedError)
      : defaultRetryableError;
    if (!isRetryableError) {
      logger.error(`Non-retryable error encountered: ${message}`, context);
      throw error; // Non-retryable error, rethrow
    }

    if (attempt >= retries) {
      logger.error(
        `Operation failed after ${retries} retries: ${(error as Error).message}`,
        context,
      );
      throw error;
    }
    // Calculate delay
    const delay = jitter
      ? calculateExponentialBackoffDelay(attempt, maxBackoff)
      : baseDelayMs * 2 ** (attempt - 1);
    logger.warn(
      `Retrying operation (${attempt}/${retries}) after error: ${(error as Error).message}`,
      context,
    );

    await new Promise((resolve) => {
      setTimeout(resolve, delay);
    });
    return exponentialBackoffRetry(
      logger,
      context,
      operation,
      retries,
      delay,
      jitter,
      attempt + 1,
      maxBackoff,
      customRetryableCheck,
    );
  }
}

import { Mutex } from 'async-mutex';

export const pendingMessageStats = {
  count: 0,
};

export const pendingMessageCountMutex = new Mutex();

/**
 * Increment the general counter
 */
export function incrementPendingMessageCount(): void {
  pendingMessageCountMutex.runExclusive(() => {
    pendingMessageStats.count += 1;
  });
}

/**
 * Decrement the general counter
 */
export function decrementPendingMessageCount(): void {
  pendingMessageCountMutex.runExclusive(() => {
    pendingMessageStats.count -= 1;
  });
}

/**
 * Return count property from pendingMessageStats
 * @returns count property
 */
export function getPendingMessagesCount(): number {
  return pendingMessageStats.count;
}

/**
 * Sleep function
 * @param time number of ms to wait
 * @returns void
 */
export async function asyncSleep(time: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, time);
  });
}

/**
 * Wraps a promise with a timeout. If the promise does not resolve or reject
 * within the specified time, the returned promise is rejected with a timeout error.
 * @template T - The resolved type of the input promise.
 * @param promise - The promise to wrap with a timeout.
 * @param ms - Timeout duration in milliseconds.
 * @returns A promise that resolves with the input promise or rejects if the timeout is exceeded.
 * @throws {Error} Throws "Operation timed out" if the promise does not settle within the given time.
 */
export async function withTimeout<T>(
  promise: Promise<T>,
  ms: number,
): Promise<T> {
  let timeoutId: ReturnType<typeof setTimeout>;
  const timeoutPromise = new Promise<never>((_, reject) => {
    timeoutId = setTimeout(() => reject(new Error('Operation timed out')), ms);
  });
  return Promise.race([promise, timeoutPromise]).finally(() =>
    clearTimeout(timeoutId),
  );
}

