## Configuration Examples

### LOIWCS v3 (deeply nested IDoc)

```typescript
export const LOIWCS_V3_CONFIG: IdocMappingConfig = {
  id: 'LOIWCS::v3',
  mestyp: 'LOIWCS',
  segments: [
    {
      path: 'E1CRHDL.ZMII_E1CRHDL',   // ← deep nesting via dot-path
      fields: [
        { source: 'EQUNR', target: 'equipmentId', transforms: ['trim'] },
        { source: 'HESSION_EQ_DESC', target: 'description' },
        { source: 'SWERK', target: 'site' },
      ],
    },
    {
      path: 'E1CRHDL.E1CRTXL',
      array: 'firstWithProp',          // ← pick first with KTEXT
      arrayProp: 'KTEXT',
      arrayItemSubPath: 'KTEXT',       // ← extract the sub-property
      fields: [
        { source: 'KTEXT', target: 'objectDescription' },
      ],
    },
  ],
};
```

### LOIWCS v2 (flat IDoc — same fields, different structure)

```typescript
export const LOIWCS_V2_CONFIG: IdocMappingConfig = {
  id: 'LOIWCS::v2',
  mestyp: 'LOIWCS',
  segments: [
    {
      path: 'ZMII_E1CRHDL',           // ← flat (no E1CRHDL wrapper)
      fields: [
        { source: 'EQUNR', target: 'equipmentId', transforms: ['trim'] },
        { source: 'HESSION_EQ_DESC', target: 'description' },
        { source: 'SWERK', target: 'site' },
      ],
    },
    {
      path: 'E1CRTXL',
      array: 'firstWithProp',
      arrayProp: 'KTEXT',
      arrayItemSubPath: 'KTEXT',
      fields: [
        { source: 'KTEXT', target: 'objectDescription' },
      ],
    },
  ],
};
```

### LOIRNH v1 (repeating hierarchy segments)

```typescript
export const LOIRNH_V1_DIRECT_CONFIG: IdocMappingConfig = {
  id: 'LOIRNH::v1-direct',
  mestyp: 'LOIRNH',
  segments: [
    {
      path: 'E1CRHSL',
      array: 'all',                    // ← one record per hierarchy link
      fields: [
        { source: 'OBJNR', target: 'objectId' },
        { source: 'HESSION_OBJNR_SUP', target: 'parentObjectId' },
        { source: 'SWERK', target: 'site' },
      ],
    },
  ],
};
```

