## How to Add a New IDoc Mapping

### Step 1 — Analyze the IDoc Structure

Examine a sample IDoc JSON to understand the segment structure:

```json
{
  "NEWIDOC01": {
    "IDOC": {
      "EDI_DC40": { "MESTYP": "NEWIDOC", "SNDPRN": "CLNT800" },
      "E1HEADER": {
        "FIELD_A": "value_a",
        "E1DETAIL": [
          { "ITEM_X": "x1", "ITEM_Y": "100" },
          { "ITEM_X": "x2", "ITEM_Y": "200" }
        ]
      }
    }
  }
}
```

### Step 2 — Define the Typed Payload Interface

```typescript
// interfaces/new-payload.interface.ts
export interface NewPayload {
  erpSource: string;
  fieldA: string;
}

export interface NewItemPayload {
  itemX: string;
  itemY: number;
  erpSource: string;
}
```

### Step 3 — Create `IdocMappingConfig`

Map the IDoc structure to a config using dot-paths:

```typescript
// new-mapping.config.ts
import { IdocMappingConfig } from '@/common/mapping/service/idoc-mapper-engine';

export const NEW_HEADER_CONFIG: IdocMappingConfig = {
  id: 'NEWIDOC::v1',
  mestyp: 'NEWIDOC',
  segments: [
    {
      path: 'EDI_DC40',
      fields: [
        { source: 'SNDPRN', target: 'erpSource', transforms: ['erpSource'] },
      ],
    },
    {
      path: 'E1HEADER',
      fields: [
        { source: 'FIELD_A', target: 'fieldA' },
      ],
    },
  ],
};

export const NEW_ITEMS_CONFIG: IdocMappingConfig = {
  id: 'NEWIDOC_ITEMS::v1',
  mestyp: 'NEWIDOC',
  segments: [
    {
      path: 'E1HEADER.E1DETAIL',
      array: 'all',
      fields: [
        { source: 'ITEM_X', target: 'itemX' },
        { source: 'ITEM_Y', target: 'itemY', transforms: ['float'] },
        { fromContext: 'erpSource', target: 'erpSource' },
      ],
    },
  ],
};
```

### Step 4 — Use in Handler

```typescript
// new.handler.ts
@IdocHandler('newidoc')
@Injectable()
export class NewHandler implements IIdocHandler {
  private readonly metadata: IdocHandlerMetadata = {
    description: 'NEWIDOC handler',
    idocFamily: 'NEWIDOC',
    version: 'v1',
  };

  constructor(private readonly newService: NewService) {}

  canHandle(rawPayload: Record<string, unknown>): boolean {
    return matchesMestyp(rawPayload, 'NEWIDOC');
  }

  getMetadata(): IdocHandlerMetadata {
    return this.metadata;
  }

  async process(rawPayload: Record<string, unknown>): Promise<void> {
    const [header] = extractIdocFields<NewPayload>(rawPayload, NEW_HEADER_CONFIG);
    const items = extractIdocFields<NewItemPayload>(
      rawPayload, NEW_ITEMS_CONFIG, { erpSource: header.erpSource },
    );

    await this.newService.upsert(header, items);
  }
}
```

### Step 5 — Wire Module + Dapr Binding

See [IDOC_INTEGRATION_GUIDE.md](./IDOC_INTEGRATION_GUIDE.md) for the full module wiring, Dapr binding, and controller endpoint steps.

